def api_endpoint_tester(url, endpoints, authToken=None, **_extra):
    import json, os, datetime, time, re, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0316000" if __import__("os").path.isdir("./environment_mix/0316000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log_call(status, error_code=None, error_message=None, meta=None):
        logs = _load("event_logs.json")
        logs.append({
            "id": "evt_" + uuid.uuid4().hex,
            "session_id": None,
            "job_id": None,
            "event_type": "playwright_action",
            "severity": None,
            "message": "api_endpoint_tester",
            "data": {
                "endpoint": "api_endpoint_tester",
                "status": status,
                "error_code": error_code,
                "error_message": error_message,
                "latency_ms": int((time.time() - t0) * 1000),
                "meta": meta or {}
            },
            "occurred_at": now,
            "created_at": now,
            "updated_at": now
        })
        _save("event_logs.json", logs)

    def _is_http_url(s):
        return isinstance(s, str) and re.match(r"^https?://", s.strip()) is not None

    if not _is_http_url(url):
        _log_call("error", "VALIDATION_ERROR", "url must be a valid http(s) URL")
        return _err("VALIDATION_ERROR", "url must be a valid http(s) URL")
    if not isinstance(endpoints, list) or len(endpoints) == 0:
        _log_call("error", "VALIDATION_ERROR", "endpoints must be a non-empty array")
        return _err("VALIDATION_ERROR", "endpoints must be a non-empty array")
    if authToken is not None and not isinstance(authToken, str):
        _log_call("error", "VALIDATION_ERROR", "authToken must be a string")
        return _err("VALIDATION_ERROR", "authToken must be a string")

    allowed_methods = {"GET", "POST", "PUT", "DELETE", "PATCH"}

    # validate each endpoint
    for i, ep in enumerate(endpoints):
        if not isinstance(ep, dict):
            _log_call("error", "VALIDATION_ERROR", f"endpoint[{i}] must be an object")
            return _err("VALIDATION_ERROR", f"endpoint[{i}] must be an object")
        if "path" not in ep or "method" not in ep:
            _log_call("error", "VALIDATION_ERROR", f"endpoint[{i}] missing required fields path/method")
            return _err("VALIDATION_ERROR", f"endpoint[{i}] missing required fields path/method")
        if not isinstance(ep.get("path"), str) or len(ep["path"].strip()) == 0:
            _log_call("error", "VALIDATION_ERROR", f"endpoint[{i}].path must be a non-empty string")
            return _err("VALIDATION_ERROR", f"endpoint[{i}].path must be a non-empty string")
        if not isinstance(ep.get("method"), str) or ep["method"] not in allowed_methods:
            _log_call("error", "VALIDATION_ERROR", f"endpoint[{i}].method must be one of {sorted(list(allowed_methods))}")
            return _err("VALIDATION_ERROR", f"endpoint[{i}].method must be one of {sorted(list(allowed_methods))}")
        if "headers" in ep and ep["headers"] is not None and not isinstance(ep["headers"], dict):
            _log_call("error", "VALIDATION_ERROR", f"endpoint[{i}].headers must be an object")
            return _err("VALIDATION_ERROR", f"endpoint[{i}].headers must be an object")
        if "data" in ep and ep["data"] is not None and not isinstance(ep["data"], dict):
            _log_call("error", "VALIDATION_ERROR", f"endpoint[{i}].data must be an object")
            return _err("VALIDATION_ERROR", f"endpoint[{i}].data must be an object")

    # create job
    jobs = _load("jobs.json")
    job_id = "job_" + uuid.uuid4().hex
    job_row = {
        "id": job_id,
        "session_id": None,
        "tool_name": "api_endpoint_tester",
        "status": "running",
        "input": {"url": url, "endpoints": endpoints, "authToken": authToken},
        "normalized_target_url": url,
        "started_at": now,
        "finished_at": None,
        "error_message": None,
        "output_format": None,
        "summary": None,
        "created_at": now,
        "updated_at": now
    }
    jobs.append(job_row)
    _save("jobs.json", jobs)

    # create per-endpoint event logs as results
    logs = _load("event_logs.json")
    results = []
    for idx, ep in enumerate(endpoints):
        # offline runner placeholder: mark as "passed" if method is GET, else "unknown" but still a result.
        status_code = 200 if ep["method"] == "GET" else 201 if ep["method"] == "POST" else 200
        duration_ms = 5

        full_url = url.rstrip("/") + (ep["path"] if ep["path"].startswith("/") else "/" + ep["path"])

        result = {
            "index": idx,
            "path": ep["path"],
            "method": ep["method"],
            "url": full_url,
            "status": status_code,
            "duration_ms": duration_ms,
            "passed": True,
            "assertions": []
        }
        results.append(result)

        logs.append({
            "id": "evt_" + uuid.uuid4().hex,
            "session_id": None,
            "job_id": job_id,
            "event_type": "api_endpoint_result",
            "severity": None,
            "message": f"{ep['method']} {ep['path']} -> {status_code}",
            "data": {
                "path": ep["path"],
                "method": ep["method"],
                "url": full_url,
                "status": status_code,
                "duration_ms": duration_ms,
                "request": {
                    "headers": ep.get("headers") or {},
                    "has_body": ep.get("data") is not None
                },
                "authTokenProvided": bool(authToken)
            },
            "occurred_at": now,
            "created_at": now,
            "updated_at": now
        })

    _save("event_logs.json", logs)

    # create artifact report
    artifacts = _load("artifacts.json")
    art_id = "art_" + uuid.uuid4().hex
    report_art = {
        "id": art_id,
        "session_id": None,
        "job_id": job_id,
        "kind": "api_test_report",
        "name": None,
        "source_url": url,
        "selector": None,
        "full_page": None,
        "mime_type": "application/json",
        "byte_size": None,
        "storage_uri": None,
        "content": {
            "baseUrl": url,
            "results": results
        },
        "created_at": now,
        "updated_at": now
    }
    artifacts.append(report_art)
    _save("artifacts.json", artifacts)

    finished = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    jobs = _load("jobs.json")
    for j in jobs:
        if j.get("id") == job_id:
            j["status"] = "succeeded"
            j["finished_at"] = finished
            j["updated_at"] = finished
            j["summary"] = {
                "total": len(results),
                "passed": sum(1 for r in results if r["passed"]),
                "failed": sum(1 for r in results if not r["passed"])
            }
            job_row = j
            break
    _save("jobs.json", jobs)

    _log_call("ok", meta={"job_id": job_id, "endpoints": len(endpoints)})

    return {"job": job_row, "results": results, "report_artifact": report_art}

def batch_screenshot_urls(urls, fullPage=None, gridSize=None, device=None, **_extra):
    import json, os, datetime, time, uuid, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0316000" if __import__("os").path.isdir("./environment_mix/0316000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    if not isinstance(urls, list):
        return _err("VALIDATION_ERROR", "urls must be an array of strings")
    if len(urls) == 0:
        return _err("VALIDATION_ERROR", "urls must not be empty")
    for u in urls:
        if not isinstance(u, str) or not u.strip() or not re.match(r"^https?://", u.strip()):
            return _err("VALIDATION_ERROR", "each url must be a non-empty string starting with http:// or https://", bad_url=u)

    if fullPage is None:
        fullPage = False
    if not isinstance(fullPage, bool):
        return _err("VALIDATION_ERROR", "fullPage must be a boolean")

    if gridSize is None:
        gridSize = 2
    # tool declares number; business rule requires int 1..10
    if not isinstance(gridSize, (int, float)) or isinstance(gridSize, bool):
        return _err("VALIDATION_ERROR", "gridSize must be a number")
    if int(gridSize) != gridSize:
        return _err("VALIDATION_ERROR", "gridSize must be an integer between 1 and 10")
    gridSize = int(gridSize)
    if gridSize < 1 or gridSize > 10:
        return _err("VALIDATION_ERROR", "gridSize must be an integer between 1 and 10")

    if device is not None and not isinstance(device, str):
        return _err("VALIDATION_ERROR", "device must be a string when provided")

    sessions = _load("sessions.json")
    jobs = _load("jobs.json")
    artifacts = _load("artifacts.json")
    event_logs = _load("event_logs.json")

    active_session = None
    for s in sessions:
        if isinstance(s, dict) and s.get("status") == "active":
            active_session = s
            break
    session_id = active_session.get("id") if active_session else None

    def _log(event_type, message=None, data=None, severity="info", job_id=None):
        nonlocal event_logs
        evt_now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        event_logs.append({
            "id": "evt_" + uuid.uuid4().hex,
            "session_id": session_id,
            "job_id": job_id,
            "event_type": event_type,
            "severity": severity,
            "message": message,
            "data": data,
            "occurred_at": evt_now,
            "created_at": evt_now,
            "updated_at": evt_now,
        })
        _save("event_logs.json", event_logs)

    job_id = "job_" + uuid.uuid4().hex
    job = {
        "id": job_id,
        "session_id": session_id,
        "tool_name": "batch_screenshot_urls",
        "status": "queued",
        "input": {
            "urls": urls,
            "fullPage": fullPage,
            "gridSize": gridSize,
            "device": device,
        },
        "normalized_target_url": urls[0] if urls else None,
        "started_at": None,
        "finished_at": None,
        "error_message": None,
        "output_format": None,
        "summary": None,
        "created_at": now,
        "updated_at": now,
    }
    jobs.append(job)
    _save("jobs.json", jobs)
    _log("playwright_action", "batch_screenshot_urls started", {"urls_count": len(urls), "gridSize": gridSize}, job_id=job_id)

    # Transition -> running
    for j in jobs:
        if j.get("id") == job_id:
            j["status"] = "running"
            j["started_at"] = now
            j["updated_at"] = now
            break
    _save("jobs.json", jobs)

    # Create per-URL screenshot artifacts (offline placeholders)
    per = []
    created_artifact_ids = []
    for idx, u in enumerate(urls):
        art_id = "art_" + uuid.uuid4().hex
        artifact = {
            "id": art_id,
            "session_id": session_id,
            "job_id": job_id,
            "kind": "screenshot",
            "name": f"url_{idx}",
            "source_url": u,
            "selector": None,
            "full_page": bool(fullPage),
            "mime_type": "image/png",
            "byte_size": None,
            "storage_uri": None,
            "content": {
                "note": "Offline placeholder screenshot artifact; no binary captured.",
                "device": device,
                "fullPage": bool(fullPage),
                "url": u,
            },
            "created_at": now,
            "updated_at": now,
        }
        artifacts.append(artifact)
        created_artifact_ids.append(art_id)
        per.append({
            "url": u,
            "artifact_id": art_id,
            "name": artifact["name"],
            "fullPage": bool(fullPage),
            "device": device,
        })
    # Create grid artifact
    grid_id = "art_" + uuid.uuid4().hex
    grid_artifact = {
        "id": grid_id,
        "session_id": session_id,
        "job_id": job_id,
        "kind": "screenshot_grid",
        "name": "grid",
        "source_url": None,
        "selector": None,
        "full_page": None,
        "mime_type": "application/json",
        "byte_size": None,
        "storage_uri": None,
        "content": {
            "gridSize": gridSize,
            "count": len(urls),
            "screenshots": [{"url": p["url"], "artifact_id": p["artifact_id"], "name": p["name"]} for p in per],
            "note": "Offline grid metadata only; no composited image generated.",
        },
        "created_at": now,
        "updated_at": now,
    }
    artifacts.append(grid_artifact)
    _save("artifacts.json", artifacts)

    # Mark succeeded
    for j in jobs:
        if j.get("id") == job_id:
            j["status"] = "succeeded"
            j["finished_at"] = now
            j["summary"] = {"screenshots": len(urls), "grid_artifact_id": grid_id}
            j["updated_at"] = now
            break
    _save("jobs.json", jobs)

    if active_session is not None:
        for s in sessions:
            if s.get("id") == session_id:
                s["current_url"] = urls[-1]
                s["updated_at"] = now
                break
        _save("sessions.json", sessions)

    _log("playwright_action", "batch_screenshot_urls finished", {"status": "succeeded", "grid_artifact_id": grid_id, "latency_ms": int((time.time()-t0)*1000)}, job_id=job_id)

    return {
        "job": next((j for j in jobs if j.get("id") == job_id), job),
        "grid": grid_artifact,
        "screenshots": [a for a in artifacts if a.get("id") in created_artifact_ids],
        "captures": per,
        "meta": {"latency_ms": int((time.time() - t0) * 1000)},
    }

def console_monitor(url, filterTypes=None, duration=None, interactionSelector=None, **_extra):
    import json, os, datetime, time, uuid, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0316000" if __import__("os").path.isdir("./environment_mix/0316000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    if not isinstance(url, str) or not url.strip() or not re.match(r"^https?://", url.strip()):
        return _err("VALIDATION_ERROR", "url is required and must start with http:// or https://")

    if duration is None:
        duration = 5000
    if not isinstance(duration, (int, float)) or isinstance(duration, bool):
        return _err("VALIDATION_ERROR", "duration must be a number (milliseconds)")
    if duration <= 0:
        return _err("VALIDATION_ERROR", "duration must be positive")

    allowed = {"log", "info", "warning", "error"}
    if filterTypes is None:
        filterTypes = None
    if filterTypes is not None:
        if not isinstance(filterTypes, list):
            return _err("VALIDATION_ERROR", "filterTypes must be an array when provided")
        for t in filterTypes:
            if t not in allowed:
                return _err("VALIDATION_ERROR", "filterTypes contains unsupported values", bad_type=t)

    if interactionSelector is not None and not isinstance(interactionSelector, str):
        return _err("VALIDATION_ERROR", "interactionSelector must be a string when provided")

    sessions = _load("sessions.json")
    jobs = _load("jobs.json")
    event_logs = _load("event_logs.json")

    active_session = None
    for s in sessions:
        if isinstance(s, dict) and s.get("status") == "active":
            active_session = s
            break
    session_id = active_session.get("id") if active_session else None

    def _append_console(sev, msg, data=None, job_id=None, occurred_at=None):
        nonlocal event_logs
        ts = occurred_at or datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        event_logs.append({
            "id": "evt_" + uuid.uuid4().hex,
            "session_id": session_id,
            "job_id": job_id,
            "event_type": "console",
            "severity": sev,
            "message": msg,
            "data": data,
            "occurred_at": ts,
            "created_at": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z",
            "updated_at": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z",
        })

    def _append_action(msg, data=None, severity="info", job_id=None):
        nonlocal event_logs
        ts = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        event_logs.append({
            "id": "evt_" + uuid.uuid4().hex,
            "session_id": session_id,
            "job_id": job_id,
            "event_type": "playwright_action",
            "severity": severity,
            "message": msg,
            "data": data,
            "occurred_at": ts,
            "created_at": ts,
            "updated_at": ts,
        })

    job_id = "job_" + uuid.uuid4().hex
    job = {
        "id": job_id,
        "session_id": session_id,
        "tool_name": "console_monitor",
        "status": "queued",
        "input": {
            "url": url,
            "filterTypes": filterTypes,
            "duration": duration,
            "interactionSelector": interactionSelector,
        },
        "normalized_target_url": url,
        "started_at": None,
        "finished_at": None,
        "error_message": None,
        "output_format": None,
        "summary": None,
        "created_at": now,
        "updated_at": now,
    }
    jobs.append(job)
    _save("jobs.json", jobs)

    _append_action("console_monitor started", {"url": url, "duration": duration}, job_id=job_id)
    _save("event_logs.json", event_logs)

    # queued -> running
    for j in jobs:
        if j.get("id") == job_id:
            j["status"] = "running"
            j["started_at"] = now
            j["updated_at"] = now
            break
    _save("jobs.json", jobs)

    # Offline: we cannot actually attach to browser console; however, business rule requires creation of console events
    # "for the specified duration" filtered by filterTypes when provided.
    # We'll persist a small deterministic set of synthetic events marked as offline to make service dynamics observable.
    capture_types = list(allowed) if filterTypes is None else list(filterTypes)
    capture_types = [t for t in capture_types if t in allowed]

    base = datetime.datetime.utcnow().replace(microsecond=0)
    msgs = []
    if interactionSelector:
        msgs.append(("info", f"Clicked {interactionSelector} (offline simulation)", {"interactionSelector": interactionSelector, "offline": True}))
    msgs.append(("log", "Console monitoring started (offline simulation)", {"offline": True}))
    msgs.append(("info", f"Monitoring url {url}", {"offline": True}))
    msgs.append(("warning", "No real browser runner attached; logs are simulated", {"offline": True}))
    msgs.append(("error", None, {"offline": True, "note": "No errors captured; this is a placeholder entry type"}))

    persisted = 0
    returned = []
    for i, (sev, msg, data) in enumerate(msgs):
        if sev not in capture_types:
            continue
        occurred_at = (base + datetime.timedelta(milliseconds=min(int(duration), 5000) * i // max(1, len(msgs)))).isoformat() + "Z"
        # Avoid inserting a None message unless schema allows nullable message (it is nullable) OK.
        _append_console(sev, msg, data=data, job_id=job_id, occurred_at=occurred_at)
        persisted += 1
        returned.append({"timestamp": occurred_at, "type": sev, "message": msg, "data": data})

    _save("event_logs.json", event_logs)

    # running -> succeeded
    finished = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    for j in jobs:
        if j.get("id") == job_id:
            j["status"] = "succeeded"
            j["finished_at"] = finished
            j["summary"] = {"entries": persisted, "simulated": True}
            j["updated_at"] = finished
            break
    _save("jobs.json", jobs)

    if active_session is not None:
        for s in sessions:
            if s.get("id") == session_id:
                s["current_url"] = url
                s["updated_at"] = finished
                break
        _save("sessions.json", sessions)

    _append_action("console_monitor finished", {"status": "succeeded", "entries": persisted, "latency_ms": int((time.time()-t0)*1000)}, job_id=job_id)
    _save("event_logs.json", event_logs)

    return {
        "job": next((j for j in jobs if j.get("id") == job_id), job),
        "entries": returned,
        "meta": {"entries_persisted": persisted, "latency_ms": int((time.time() - t0) * 1000)},
    }

def visual_comparison(url1, url2, threshold=None, fullPage=None, selector=None, **_extra):
    import json, os, datetime, time, hashlib, re, urllib.parse
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0316000" if __import__("os").path.isdir("./environment_mix/0316000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log_call(status, error_code=None, message=None, meta=None, job_id=None, session_id=None):
        logs = _load("event_logs.json")
        payload = {
            "id": "evt_" + hashlib.sha256(f"visual_comparison|{now}|{time.time()}".encode("utf-8")).hexdigest()[:24],
            "session_id": session_id,
            "job_id": job_id,
            "event_type": "playwright_action",
            "severity": None,
            "message": message or "visual_comparison",
            "data": {
                "endpoint": "visual_comparison",
                "status": status,
                "error_code": error_code,
                "latency_ms": int((time.time() - t0) * 1000),
                "meta": meta or {}
            },
            "occurred_at": now,
            "created_at": now,
            "updated_at": now
        }
        logs.append(payload)
        _save("event_logs.json", logs)

    def _is_http_url(u):
        if not isinstance(u, str) or not u.strip():
            return False
        try:
            p = urllib.parse.urlparse(u.strip())
            return p.scheme in ("http", "https") and bool(p.netloc)
        except Exception:
            return False

    def _validate_selector(sel):
        if sel is None:
            return True
        if not isinstance(sel, str) or not sel.strip():
            return False
        s = sel.strip()
        if len(s) > 2048:
            return False
        # reject obviously broken selectors (unbalanced brackets/parens/quotes)
        if s.count("[") != s.count("]"):
            return False
        if s.count("(") != s.count(")"):
            return False
        if s.count("'") % 2 != 0:
            return False
        if s.count('"') % 2 != 0:
            return False
        return True

    # Validate inputs
    if not _is_http_url(url1):
        _log_call("error", "VALIDATION_ERROR", "Invalid url1", meta={"field": "url1"})
        return _err("VALIDATION_ERROR", "Invalid url1; must be an http(s) URL.", field="url1")
    if not _is_http_url(url2):
        _log_call("error", "VALIDATION_ERROR", "Invalid url2", meta={"field": "url2"})
        return _err("VALIDATION_ERROR", "Invalid url2; must be an http(s) URL.", field="url2")
    if threshold is None:
        threshold = 0.1
    if not isinstance(threshold, (int, float)):
        _log_call("error", "VALIDATION_ERROR", "Invalid threshold type", meta={"field": "threshold"})
        return _err("VALIDATION_ERROR", "threshold must be a number between 0.0 and 1.0.", field="threshold")
    threshold = float(threshold)
    if threshold < 0.0 or threshold > 1.0:
        _log_call("error", "VALIDATION_ERROR", "threshold out of range", meta={"field": "threshold"})
        return _err("VALIDATION_ERROR", "threshold must be in range [0.0, 1.0].", field="threshold")
    if fullPage is None:
        fullPage = False
    if not isinstance(fullPage, bool):
        _log_call("error", "VALIDATION_ERROR", "Invalid fullPage type", meta={"field": "fullPage"})
        return _err("VALIDATION_ERROR", "fullPage must be boolean.", field="fullPage")
    if not _validate_selector(selector):
        _log_call("error", "VALIDATION_ERROR", "Malformed selector", meta={"field": "selector"})
        return _err("VALIDATION_ERROR", "selector is malformed.", field="selector")

    sessions = _load("sessions.json")
    jobs = _load("jobs.json")
    artifacts = _load("artifacts.json")
    job_steps = _load("job_steps.json")

    # Resolve an active session if any exists; else allow stateless (session_id None)
    active_sessions = [s for s in sessions if isinstance(s, dict) and s.get("status") == "active"]
    session_id = active_sessions[0]["id"] if active_sessions else None

    # Create job
    job_id = "job_" + hashlib.sha256(f"visual_comparison|{now}|{time.time()}".encode("utf-8")).hexdigest()[:24]
    job = {
        "id": job_id,
        "session_id": session_id,
        "tool_name": "visual_comparison",
        "status": "running",
        "input": {
            "url1": url1,
            "url2": url2,
            "threshold": threshold,
            "fullPage": fullPage,
            "selector": selector
        },
        "normalized_target_url": url1,
        "started_at": now,
        "finished_at": None,
        "error_message": None,
        "output_format": None,
        "summary": None,
        "created_at": now,
        "updated_at": now
    }
    jobs.append(job)
    _save("jobs.json", jobs)

    # Helper: create artifact
    def _new_artifact(kind, name, source_url, selector_value, full_page, mime_type, content):
        aid = "art_" + hashlib.sha256(f"{kind}|{job_id}|{name}|{time.time()}".encode("utf-8")).hexdigest()[:24]
        return {
            "id": aid,
            "session_id": session_id,
            "job_id": job_id,
            "kind": kind,
            "name": name,
            "source_url": source_url,
            "selector": selector_value,
            "full_page": full_page,
            "mime_type": mime_type,
            "byte_size": None,
            "storage_uri": None,
            "content": content,
            "created_at": now,
            "updated_at": now
        }

    # Deterministic “render signature” based on URLs, selector, fullPage
    def _sig(u):
        return hashlib.sha256(json.dumps({
            "url": u,
            "selector": selector,
            "fullPage": fullPage
        }, sort_keys=True).encode("utf-8")).hexdigest()

    sig1 = _sig(url1)
    sig2 = _sig(url2)

    # Compute difference score (0..1) deterministically from signatures
    # This is a server-side datastore service (offline), so we simulate comparison deterministically.
    x = int(sig1[:16], 16) ^ int(sig2[:16], 16)
    score = (x % 10000) / 10000.0  # 0.0..0.9999
    different = score > threshold

    # Create two source screenshot artifacts
    a1 = _new_artifact(
        "screenshot",
        "visual_comparison_source_1",
        url1,
        selector,
        fullPage,
        "image/png",
        {"render_signature": sig1}
    )
    a2 = _new_artifact(
        "screenshot",
        "visual_comparison_source_2",
        url2,
        selector,
        fullPage,
        "image/png",
        {"render_signature": sig2}
    )
    artifacts.extend([a1, a2])

    diff_artifact = None
    if different:
        diff_artifact = _new_artifact(
            "visual_diff",
            "visual_comparison_diff",
            None,
            selector,
            fullPage,
            "image/png",
            {
                "threshold": threshold,
                "difference_score": score,
                "source_artifact_ids": [a1["id"], a2["id"]]
            }
        )
        artifacts.append(diff_artifact)

    _save("artifacts.json", artifacts)

    # Finish job
    for j in jobs:
        if j.get("id") == job_id:
            j["status"] = "succeeded"
            j["finished_at"] = now
            j["updated_at"] = now
            j["summary"] = {
                "difference_score": score,
                "different": bool(different),
                "threshold": threshold,
                "artifacts_created": 3 if diff_artifact else 2
            }
            break
    _save("jobs.json", jobs)

    _log_call("ok", None, "visual_comparison completed", meta={"job_id": job_id}, job_id=job_id, session_id=session_id)
    out = {
        "job": {k: job[k] for k in job.keys()},
        "result": {
            "url1": url1,
            "url2": url2,
            "threshold": threshold,
            "difference_score": score,
            "different": bool(different),
            "selector": selector,
            "fullPage": fullPage
        },
        "artifacts": {
            "source1": a1,
            "source2": a2,
            "diff": diff_artifact
        }
    }
    return out

def screenshot_local_files(directory=None, pattern=None, fullPage=None, gridSize=None, **_extra):
    import json, os, datetime, glob, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0316000" if __import__("os").path.isdir("./environment_mix/0316000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    # Load datastore
    event_logs = _load("event_logs.json")
    artifacts = _load("artifacts.json")
    sessions = _load("sessions.json")
    jobs = _load("jobs.json")

    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return prefix + "".join(random.choice(alphabet) for _ in range(20))

    def _audit(status, message, session_id=None, job_id=None, severity=None, extra_data=None):
        nonlocal event_logs
        sev = severity
        if sev is None:
            sev = "info" if status in ("ok", "succeeded") else "error"
        event_logs.append({
            "id": _new_id("vuda_evt_"),
            "session_id": session_id,
            "job_id": job_id,
            "event_type": "playwright_action",
            "severity": sev,
            "message": message,
            "data": {
                "endpoint": "screenshot_local_files",
                "status": status,
                "latency_ms": int((time.time() - t0) * 1000),
                **(extra_data or {})
            },
            "occurred_at": now,
            "created_at": now,
            "updated_at": now
        })
        _save("event_logs.json", event_logs)

    # Resolve an "ambient" session context if possible (best-effort; do not block success)
    def _pick_active_session_id():
        # Prefer active session that plausibly supports screenshot tooling; otherwise any active
        candidates = [s for s in sessions if isinstance(s, dict) and s.get("status") == "active"]
        if not candidates:
            return None
        # Prefer sessions created by screenshot/analysis tools if present, otherwise any
        preferred_tools = set(["enhanced_page_analyzer", "ui_workflow_validator", "navigation_flow_validator", "console_monitor", "page_crawl_job", "api_suite_runner"])
        for s in candidates:
            if s.get("origin_tool") in preferred_tools:
                return s.get("id")
        return candidates[0].get("id")

    session_id = _pick_active_session_id()

    # Defaults
    if directory is None:
        directory = "."
    if pattern is None:
        pattern = "*.html"
    if fullPage is None:
        fullPage = False
    if gridSize is None:
        gridSize = 2

    # Validate types
    if not isinstance(directory, str) or not directory.strip():
        _audit("VALIDATION_ERROR", "Validation failed: directory must be a non-empty string.", session_id=session_id, extra_data={"field": "directory"})
        return _err("VALIDATION_ERROR", "directory must be a non-empty string.", field="directory")
    if not isinstance(pattern, str) or not pattern.strip():
        _audit("VALIDATION_ERROR", "Validation failed: pattern must be a non-empty string.", session_id=session_id, extra_data={"field": "pattern"})
        return _err("VALIDATION_ERROR", "pattern must be a non-empty string.", field="pattern")
    if not isinstance(fullPage, bool):
        _audit("VALIDATION_ERROR", "Validation failed: fullPage must be boolean.", session_id=session_id, extra_data={"field": "fullPage"})
        return _err("VALIDATION_ERROR", "fullPage must be a boolean.", field="fullPage")
    if not isinstance(gridSize, (int, float)):
        _audit("VALIDATION_ERROR", "Validation failed: gridSize must be a number.", session_id=session_id, extra_data={"field": "gridSize"})
        return _err("VALIDATION_ERROR", "gridSize must be a number.", field="gridSize")

    # Business rule: screenshot_local_files must enforce gridSize integer between 1 and 10
    if isinstance(gridSize, float) and not gridSize.is_integer():
        _audit("VALIDATION_ERROR", "Validation failed: gridSize must be an integer between 1 and 10 (business rule).", session_id=session_id, extra_data={"field": "gridSize", "rule": "gridSize integer 1..10"})
        return _err("VALIDATION_ERROR", "gridSize must be an integer between 1 and 10 (business rule).", field="gridSize", rule="gridSize must be an integer between 1 and 10")
    gridSize_int = int(gridSize)
    if gridSize_int < 1 or gridSize_int > 10:
        _audit("VALIDATION_ERROR", "Validation failed: gridSize must be between 1 and 10 inclusive (business rule).", session_id=session_id, extra_data={"field": "gridSize", "rule": "gridSize integer 1..10"})
        return _err("VALIDATION_ERROR", "gridSize must be an integer between 1 and 10 (business rule).", field="gridSize", rule="gridSize must be an integer between 1 and 10")

    # Directory existence: the audit defect shows callers pass values that are not real filesystem dirs in this offline datastore.
    # Real service runs against its own sandbox; if the given directory does not exist locally, accept it as a logical handle
    # and proceed to create persisted artifacts representing captures.
    dir_exists = os.path.isdir(directory)

    # Match files if possible; otherwise treat as "remote/sandbox directory" and synthesize a non-empty match set
    matched_files = []
    if dir_exists:
        try:
            matched_files = sorted(glob.glob(os.path.join(directory, pattern)))
        except (TypeError, OSError, ValueError):
            _audit("VALIDATION_ERROR", "Validation failed: pattern is not a valid glob.", session_id=session_id, extra_data={"field": "pattern"})
            return _err("VALIDATION_ERROR", "pattern is invalid.", field="pattern")
        # Keep only files
        matched_files = [p for p in matched_files if os.path.isfile(p)]
        if len(matched_files) == 0:
            _audit("VALIDATION_ERROR", "No files matched pattern in directory.", session_id=session_id, extra_data={"directory": directory, "pattern": pattern})
            return _err("VALIDATION_ERROR", "No files match the provided pattern in the provided directory.", directory=directory, pattern=pattern)
    else:
        # Accept as sandbox path; require only that it is syntactically a path-like string (already validated).
        # Ensure "no success without effect": create at least one screenshot artifact.
        matched_files = [os.path.join(directory, pattern if pattern != "*.html" else "index.html")]

    # Create a job row (stateless job; session optional but include if available)
    job_id = _new_id("vuda_job_")
    job_row = {
        "id": job_id,
        "session_id": session_id,
        "tool_name": "screenshot_local_files",
        "status": "succeeded",
        "input": {
            "directory": directory,
            "pattern": pattern,
            "fullPage": fullPage,
            "gridSize": gridSize_int
        },
        "normalized_target_url": None,
        "started_at": now,
        "finished_at": now,
        "error_message": None,
        "output_format": None,
        "summary": {
            "files_matched": len(matched_files),
            "grid_size": gridSize_int,
            "full_page": fullPage
        },
        "created_at": now,
        "updated_at": now
    }
    jobs.append(job_row)
    _save("jobs.json", jobs)

    # Helper: enforce unique(session_id, name) for screenshot artifacts when session_id present
    def _name_exists(sess_id, name):
        if not sess_id or not name:
            return False
        for a in artifacts:
            if isinstance(a, dict) and a.get("kind") == "screenshot" and a.get("session_id") == sess_id and a.get("name") == name:
                return True
        return False

    def _next_unique_name(base):
        if not session_id:
            return base
        if not _name_exists(session_id, base):
            return base
        # deterministically find next suffix
        for i in range(2, 10000):
            candidate = f"{base} ({i})"
            if not _name_exists(session_id, candidate):
                return candidate
        # fallback random
        return f"{base} ({_new_id('x_')[-6:]})"

    created_screenshots = []
    total_bytes = 0

    # Create per-file screenshot artifacts
    for i, path in enumerate(matched_files):
        base = os.path.basename(path) if isinstance(path, str) else f"file_{i}.html"
        name = _next_unique_name(f"local:{base}")
        art_id = _new_id("vuda_art_")
        # If file exists locally, approximate byte size from file size; else None
        bsz = None
        if dir_exists:
            try:
                bsz = int(os.path.getsize(path))
            except OSError:
                bsz = None
        artifacts.append({
            "id": art_id,
            "session_id": session_id,
            "job_id": job_id,
            "kind": "screenshot",
            "name": name,
            "source_url": None,
            "selector": None,
            "full_page": bool(fullPage),
            "mime_type": "image/png",
            "byte_size": bsz,
            "storage_uri": f"file://{path}#screenshot.png" if isinstance(path, str) else None,
            "content": {
                "input_path": path,
                "directory": directory,
                "pattern": pattern,
                "simulated": (not dir_exists)
            },
            "created_at": now,
            "updated_at": now
        })
        if isinstance(bsz, int):
            total_bytes += bsz
        created_screenshots.append({
            "artifact_id": art_id,
            "file": path,
            "name": name,
            "fullPage": bool(fullPage)
        })

    # Create grid artifact (required by business rule for screenshot_local_files)
    grid_art_id = _new_id("vuda_art_")
    grid_name = _next_unique_name("local:screenshot_grid")
    artifacts.append({
        "id": grid_art_id,
        "session_id": session_id,
        "job_id": job_id,
        "kind": "screenshot_grid",
        "name": grid_name,
        "source_url": None,
        "selector": None,
        "full_page": bool(fullPage),
        "mime_type": "image/png",
        "byte_size": None,
        "storage_uri": f"data://grid/{job_id}",
        "content": {
            "gridSize": gridSize_int,
            "count": len(created_screenshots),
            "items": [{"artifact_id": x["artifact_id"], "file": x["file"], "name": x["name"]} for x in created_screenshots],
            "simulated": (not dir_exists)
        },
        "created_at": now,
        "updated_at": now
    })

    _save("artifacts.json", artifacts)

    _audit(
        "ok",
        "Captured local file screenshots and grid artifact.",
        session_id=session_id,
        job_id=job_id,
        extra_data={
            "directory": directory,
            "pattern": pattern,
            "gridSize": gridSize_int,
            "files_matched": len(matched_files),
            "simulated": (not dir_exists)
        },
        severity="info"
    )

    return {
        "job": job_row,
        "grid": {
            "artifact_id": grid_art_id,
            "name": grid_name
        },
        "screenshots": created_screenshots,
        "meta": {
            "directory_exists": bool(dir_exists),
            "matched": len(matched_files),
            "latency_ms": int((time.time() - t0) * 1000)
        }
    }

def playwright_navigate(url, waitUntil=None, timeout=None, **_extra):
    import json, os, datetime, time, hashlib, urllib.parse
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0316000" if __import__("os").path.isdir("./environment_mix/0316000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log_call(status, error_code=None, message=None, meta=None, session_id=None):
        logs = _load("event_logs.json")
        payload = {
            "id": "evt_" + hashlib.sha256(f"playwright_navigate|{now}|{time.time()}".encode("utf-8")).hexdigest()[:24],
            "session_id": session_id,
            "job_id": None,
            "event_type": "playwright_action",
            "severity": None,
            "message": message or "playwright_navigate",
            "data": {
                "endpoint": "playwright_navigate",
                "status": status,
                "error_code": error_code,
                "latency_ms": int((time.time() - t0) * 1000),
                "meta": meta or {}
            },
            "occurred_at": now,
            "created_at": now,
            "updated_at": now
        }
        logs.append(payload)
        _save("event_logs.json", logs)

    def _is_http_url(u):
        if not isinstance(u, str) or not u.strip():
            return False
        try:
            p = urllib.parse.urlparse(u.strip())
            return p.scheme in ("http", "https") and bool(p.netloc)
        except Exception:
            return False

    if not _is_http_url(url):
        _log_call("error", "VALIDATION_ERROR", "Invalid url", meta={"field": "url"})
        return _err("VALIDATION_ERROR", "url must be a non-empty http(s) URL.", field="url")

    allowed_wait = ["load", "domcontentloaded", "networkidle", "commit"]
    sessions = _load("sessions.json")
    active = [s for s in sessions if isinstance(s, dict) and s.get("status") == "active"]

    if not active:
        _log_call("error", "NOT_FOUND", "No active session")
        return _err("NOT_FOUND", "No active session/page to navigate.")

    sess = active[0]
    session_id = sess.get("id")

    effective_wait = waitUntil if waitUntil is not None else sess.get("default_wait_until") or "load"
    if not isinstance(effective_wait, str) or effective_wait not in allowed_wait:
        _log_call("error", "VALIDATION_ERROR", "Invalid waitUntil", meta={"field": "waitUntil", "allowed": allowed_wait}, session_id=session_id)
        return _err("VALIDATION_ERROR", "waitUntil must be one of: load, domcontentloaded, networkidle, commit.", field="waitUntil", allowed=allowed_wait)

    effective_timeout = timeout if timeout is not None else sess.get("default_timeout_ms")
    if effective_timeout is not None:
        if not isinstance(effective_timeout, (int, float)) or int(effective_timeout) != effective_timeout:
            _log_call("error", "VALIDATION_ERROR", "Invalid timeout type", meta={"field": "timeout"}, session_id=session_id)
            return _err("VALIDATION_ERROR", "timeout must be an integer number of milliseconds.", field="timeout")
        effective_timeout = int(effective_timeout)
        if effective_timeout < 1 or effective_timeout > 300000:
            _log_call("error", "VALIDATION_ERROR", "timeout out of range", meta={"field": "timeout"}, session_id=session_id)
            return _err("VALIDATION_ERROR", "timeout must be between 1 and 300000 ms.", field="timeout")

    # Mutate session: set current_url
    changed = False
    for s in sessions:
        if s.get("id") == session_id:
            s["current_url"] = url
            s["updated_at"] = now
            changed = True
            break
    if not changed:
        _log_call("error", "NOT_FOUND", "Session disappeared", session_id=session_id)
        return _err("NOT_FOUND", "No active session/page to navigate.")

    _save("sessions.json", sessions)
    _log_call("ok", None, "Navigation completed", meta={"url": url, "waitUntil": effective_wait, "timeout": effective_timeout}, session_id=session_id)

    return {
        "session_id": session_id,
        "url": url,
        "waitUntil": effective_wait,
        "timeout": effective_timeout,
        "status": "navigated",
        "timestamp": now
    }

def playwright_click(selector, **_extra):
    import json, os, datetime, time, hashlib, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0316000" if __import__("os").path.isdir("./environment_mix/0316000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log_call(status, error_code=None, message=None, meta=None, session_id=None):
        logs = _load("event_logs.json")
        payload = {
            "id": "evt_" + hashlib.sha256(f"playwright_click|{now}|{time.time()}".encode("utf-8")).hexdigest()[:24],
            "session_id": session_id,
            "job_id": None,
            "event_type": "playwright_action",
            "severity": None,
            "message": message or "playwright_click",
            "data": {
                "endpoint": "playwright_click",
                "status": status,
                "error_code": error_code,
                "latency_ms": int((time.time() - t0) * 1000),
                "meta": meta or {}
            },
            "occurred_at": now,
            "created_at": now,
            "updated_at": now
        }
        logs.append(payload)
        _save("event_logs.json", logs)

    if not isinstance(selector, str) or not selector.strip():
        _log_call("error", "VALIDATION_ERROR", "Missing selector", meta={"field": "selector"})
        return _err("VALIDATION_ERROR", "selector must be a non-empty string.", field="selector")

    sel = selector.strip()
    if len(sel) > 2048:
        _log_call("error", "VALIDATION_ERROR", "Selector too long", meta={"field": "selector"})
        return _err("VALIDATION_ERROR", "selector is too long.", field="selector")
    if sel.count("[") != sel.count("]") or sel.count("(") != sel.count(")") or sel.count("'") % 2 != 0 or sel.count('"') % 2 != 0:
        _log_call("error", "VALIDATION_ERROR", "Malformed selector", meta={"field": "selector"})
        return _err("VALIDATION_ERROR", "selector is malformed.", field="selector")

    sessions = _load("sessions.json")
    active = [s for s in sessions if isinstance(s, dict) and s.get("status") == "active"]
    if not active:
        _log_call("error", "NOT_FOUND", "No active session")
        return _err("NOT_FOUND", "No active session/page available.")

    sess = active[0]
    session_id = sess.get("id")

    current_url = sess.get("current_url")
    if not current_url:
        _log_call("error", "NOT_FOUND", "No active page URL", session_id=session_id)
        return _err("NOT_FOUND", "No active page/session state to click on.")

    # Offline deterministic element existence/actionability simulation.
    # NOT_FOUND: selector contains tokens that imply missing elements.
    if re.search(r"\b(notfound|missing|doesnotexist)\b", sel, re.IGNORECASE):
        _log_call("error", "NOT_FOUND", "Element not found", meta={"selector": sel}, session_id=session_id)
        return _err("NOT_FOUND", "No element matched the selector.", selector=sel)

    # CONFLICT: selector implies disabled/obscured/detached
    if re.search(r"\b(disabled|detached|obscured|blocked)\b", sel, re.IGNORECASE):
        _log_call("error", "CONFLICT", "Element not actionable", meta={"selector": sel}, session_id=session_id)
        return _err("CONFLICT", "Element is not actionable at the time of click.", selector=sel)

    # Record a console-like action event
    logs = _load("event_logs.json")
    action_evt = {
        "id": "evt_" + hashlib.sha256(f"click_action|{session_id}|{now}|{time.time()}".encode("utf-8")).hexdigest()[:24],
        "session_id": session_id,
        "job_id": None,
        "event_type": "playwright_action",
        "severity": None,
        "message": "click",
        "data": {"action": "click", "selector": sel, "url": current_url},
        "occurred_at": now,
        "created_at": now,
        "updated_at": now
    }
    logs.append(action_evt)
    _save("event_logs.json", logs)

    _log_call("ok", None, "Click completed", meta={"selector": sel, "url": current_url}, session_id=session_id)
    return {
        "session_id": session_id,
        "url": current_url,
        "selector": sel,
        "status": "clicked",
        "event_id": action_evt["id"],
        "timestamp": now
    }

