def playwright_evaluate(script, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0316000" if __import__("os").path.isdir("./environment_mix/0316000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    sessions = _load("sessions.json")
    event_logs = _load("event_logs.json")
    jobs = _load("jobs.json")

    endpoint = "playwright_evaluate"

    def _log(status, message=None, data=None, session_id=None, job_id=None):
        eid = "vuda_evt_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f")
        row = {
            "id": eid,
            "session_id": session_id,
            "job_id": job_id,
            "event_type": "playwright_action",
            "severity": None,
            "message": message,
            "data": data or {},
            "occurred_at": now,
            "created_at": now,
            "updated_at": now,
        }
        event_logs.append(row)
        _save("event_logs.json", event_logs)

    # Validation
    if not isinstance(script, str) or not script.strip():
        _log("error", message="VALIDATION_ERROR: script is required", data={"endpoint": endpoint, "status": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "`script` must be a non-empty string.")

    # Resolve an active session context (ambient auth)
    active_sessions = [s for s in sessions if isinstance(s, dict) and s.get("status") == "active"]
    if not active_sessions:
        _log("error", message="NOT_FOUND: no active session", data={"endpoint": endpoint, "status": "NOT_FOUND"})
        return _err("NOT_FOUND", "No active page/session context to evaluate against.")

    # Pick a session that appears to have a current_url context if available
    sess = None
    for s in active_sessions:
        if s.get("current_url") or s.get("start_url"):
            sess = s
            break
    if sess is None:
        sess = active_sessions[0]

    # Conflict if session is not in a usable lifecycle state (closed/closing/errored)
    if sess.get("status") != "active":
        _log("error", message="CONFLICT: invalid session context", data={"endpoint": endpoint, "status": "CONFLICT"}, session_id=sess.get("id"))
        return _err("CONFLICT", "Execution refused due to an invalid/closed page context.", sessionId=sess.get("id"))

    # "Execute" JS offline: we cannot run JS; emulate deterministic behavior:
    # - If script appears to throw, return error details
    # - Otherwise return a structured echo result
    lowered = script.strip().lower()
    if "throw" in lowered or "new error" in lowered:
        _log("ok", message="evaluate: script threw", data={"endpoint": endpoint, "status": "ok", "action": "evaluate", "script_len": len(script), "result": "error"}, session_id=sess.get("id"))
        return {
            "sessionId": sess.get("id"),
            "currentUrl": sess.get("current_url") or sess.get("start_url"),
            "ok": False,
            "error": {
                "name": "Error",
                "message": "Script threw an error (offline evaluator).",
                "stack": None,
            },
        }

    # record action log
    _log(
        "ok",
        message="evaluate: executed",
        data={
            "endpoint": endpoint,
            "status": "ok",
            "action": "evaluate",
            "script_len": len(script),
            "latency_ms": int((time.time() - t0) * 1000),
        },
        session_id=sess.get("id"),
    )

    # return "result" similar to vendor shape (best-effort)
    return {
        "sessionId": sess.get("id"),
        "currentUrl": sess.get("current_url") or sess.get("start_url"),
        "result": {
            "type": "offline_echo",
            "value": None,
            "preview": script[:500],
        },
    }

def playwright_console_logs(clear=None, limit=None, type=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0316000" if __import__("os").path.isdir("./environment_mix/0316000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    sessions = _load("sessions.json")
    event_logs = _load("event_logs.json")

    endpoint = "playwright_console_logs"

    def _append_action_log(status_code, message, session_id=None, extra=None):
        eid = "vuda_evt_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f")
        event_logs.append(
            {
                "id": eid,
                "session_id": session_id,
                "job_id": None,
                "event_type": "playwright_action",
                "severity": None,
                "message": message,
                "data": {
                    "endpoint": endpoint,
                    "status": status_code,
                    "latency_ms": int((time.time() - t0) * 1000),
                    **(extra or {}),
                },
                "occurred_at": now,
                "created_at": now,
                "updated_at": now,
            }
        )

    # Validation
    allowed_types = {"all", "error", "warning", "log", "info", "debug"}
    if type is not None:
        if not isinstance(type, str) or type not in allowed_types:
            _append_action_log("VALIDATION_ERROR", "VALIDATION_ERROR: invalid type")
            _save("event_logs.json", event_logs)
            return _err("VALIDATION_ERROR", "`type` must be one of: all, error, warning, log, info, debug.")
    if limit is not None:
        if not (isinstance(limit, int) or isinstance(limit, float)) or isinstance(limit, bool):
            _append_action_log("VALIDATION_ERROR", "VALIDATION_ERROR: invalid limit")
            _save("event_logs.json", event_logs)
            return _err("VALIDATION_ERROR", "`limit` must be a non-negative number.")
        if limit < 0:
            _append_action_log("VALIDATION_ERROR", "VALIDATION_ERROR: negative limit")
            _save("event_logs.json", event_logs)
            return _err("VALIDATION_ERROR", "`limit` must be non-negative.")
    if clear is not None and not isinstance(clear, bool):
        _append_action_log("VALIDATION_ERROR", "VALIDATION_ERROR: invalid clear")
        _save("event_logs.json", event_logs)
        return _err("VALIDATION_ERROR", "`clear` must be a boolean when provided.")

    # Resolve active session (ambient auth)
    active_sessions = [s for s in sessions if isinstance(s, dict) and s.get("status") == "active"]
    if not active_sessions:
        _append_action_log("NOT_FOUND", "NOT_FOUND: no active session")
        _save("event_logs.json", event_logs)
        return _err("NOT_FOUND", "No active page/session to read logs from.")

    sess = None
    for s in active_sessions:
        if s.get("id"):
            sess = s
            break
    if sess is None:
        sess = active_sessions[0]

    sess_id = sess.get("id")

    # Filter console events
    rows = [e for e in event_logs if isinstance(e, dict) and e.get("event_type") == "console" and e.get("session_id") == sess_id]
    # Sort by occurred_at then created_at (stable)
    def _ts(v):
        return v if isinstance(v, str) else ""
    rows.sort(key=lambda r: (_ts(r.get("occurred_at")), _ts(r.get("created_at")), r.get("id") or ""))

    if type is None:
        type = "all"
    if type != "all":
        rows = [e for e in rows if e.get("severity") == type]

    if limit is None:
        limit_n = 100
    else:
        limit_n = int(limit)

    returned = rows[:limit_n]

    # Clear behavior: delete returned rows for session
    if clear is True and returned:
        returned_ids = {r.get("id") for r in returned if r.get("id")}
        new_event_logs = [e for e in event_logs if not (isinstance(e, dict) and e.get("id") in returned_ids)]
        event_logs = new_event_logs

    _append_action_log(
        "ok",
        "console_logs: retrieved",
        session_id=sess_id,
        extra={"returned": len(returned), "filtered_type": type, "clear": bool(clear), "limit": limit_n},
    )
    _save("event_logs.json", event_logs)

    return {
        "sessionId": sess_id,
        "type": type,
        "limit": limit_n,
        "count": len(returned),
        "logs": returned,
    }

