    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return prefix + "".join(random.choice(alphabet) for _ in range(20))

    def _audit(status_code, message, session_id=None, job_id=None, extra_data=None, severity=None):
        nonlocal event_logs
        sev = severity
        if sev is None:
            sev = "info" if status_code in ("ok", "succeeded") else "error"
        event_logs.append({
            "id": _new_id("vuda_evt_"),
            "session_id": session_id,
            "job_id": job_id,
            "event_type": "playwright_action",
            "severity": sev,
            "message": message,
