                _audit("NOT_FOUND", "Job not found", session_id=sessionId, job_id=jobId)
                return _err("NOT_FOUND", "Job not found", jobId=jobId)
            if job_row.get("session_id") not in (None, sessionId):
                _audit("CONFLICT", "Job does not belong to session", session_id=sessionId, job_id=jobId)
                return _err("CONFLICT", "Job does not belong to the provided session", jobId=jobId, sessionId=sessionId)
            if job_row.get("status") == "cancelled":
                _audit("INVALID_TRANSITION", "Job is cancelled", session_id=sessionId, job_id=jobId)
                return _err("INVALID_TRANSITION", "Job is cancelled; cannot attach new artifacts.", jobId=jobId)
            job_id_effective = jobId
        else:
