    if includeHidden is None:
        includeHidden = False
    if not isinstance(includeHidden, bool):
        _audit("VALIDATION_ERROR", "Invalid includeHidden", session_id=sessionId, job_id=job_id_effective, extra_data={"field": "includeHidden"})
        return _err("VALIDATION_ERROR", "includeHidden must be boolean.", field="includeHidden")

    sess = next((s for s in sessions if isinstance(s, dict) and s.get("id") == sessionId), None)
    if not sess:
        _audit("NOT_FOUND", "Session not found", session_id=sessionId, job_id=job_id_effective)
        return _err("NOT_FOUND", "Session not found", sessionId=sessionId)

    if sess.get("status") != "active":
        _audit("INVALID_TRANSITION", "Session not active", session_id=sessionId, job_id=job_id_effective)
        return _err("INVALID_TRANSITION", "Session is not active.", sessionStatus=sess.get("status"))

    # Offline behavior: return a deterministic placeholder derived from last known session url and selector
    current_url = sess.get("current_url") or sess.get("start_url")
    text = ""
    if selector:
        text = f"[visible_text selector={selector} url={current_url or ''} includeHidden={includeHidden}]"
    else:
        text = f"[visible_text url={current_url or ''} includeHidden={includeHidden}]"

    artifact_row = None
    if job_id_effective is not None:
        art_id = _new_id("vuda_art_")
        artifact_row = {
            "id": art_id,
            "session_id": sessionId,
            "job_id": job_id_effective,
            "kind": "visible_text",
            "name": None,
            "source_url": current_url,
            "selector": selector,
            "full_page": None,
            "mime_type": "text/plain",
            "byte_size": None,
            "storage_uri": None,
            "content": {"text": text, "includeHidden": includeHidden},
            "created_at": now,
            "updated_at": now
        }
        artifacts.append(artifact_row)
        _save("artifacts.json", artifacts)

    _audit("ok", "Extracted visible text", session_id=sessionId, job_id=job_id_effective, extra_data={"selector": selector, "includeHidden": includeHidden})

    resp = {"sessionId": sessionId, "selector": selector, "includeHidden": includeHidden, "text": text}
    if artifact_row is not None:
        resp["artifact"] = artifact_row
    return resp

