    now = now_dt.isoformat() + "Z"

    sessions = _load("sessions.json")
    jobs = _load("jobs.json")
    event_logs = _load("event_logs.json")

    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return prefix + "".join(random.choice(alphabet) for _ in range(20))

    def _audit(status_code, message, session_id=None, job_id=None, extra_data=None, severity=None):
        nonlocal event_logs
        sev = severity
        if sev is None:
            sev = "info" if status_code in ("ok", "succeeded") else "error"
        event_logs.append({
            "id": _new_id("vuda_evt_"),
            "session_id": session_id,
            "job_id": job_id,
            "event_type": "playwright_action",
            "severity": sev,
            "message": message,
            "data": {"endpoint": "playwright_go_forward", "status": status_code, "latency_ms": int((time.time() - t0) * 1000), **(extra_data or {})},
            "occurred_at": now,
            "created_at": now,
            "updated_at": now
        })
        _save("event_logs.json", event_logs)

    sess_pat = re.compile(r"^vuda_sess_[0-9A-HJKMNP-TV-Z]{16,}$")
    job_pat = re.compile(r"^vuda_job_[0-9A-HJKMNP-TV-Z]{16,}$")

    if not isinstance(sessionId, str) or not sess_pat.match(sessionId):
        _audit("VALIDATION_ERROR", "Invalid sessionId", extra_data={"field": "sessionId"})
        return _err("VALIDATION_ERROR", "`sessionId` is invalid.", field="sessionId")

    if waitUntil is not None and (not isinstance(waitUntil, str) or waitUntil not in ("load", "domcontentloaded", "networkidle", "commit")):
        _audit("VALIDATION_ERROR", "Invalid waitUntil", session_id=sessionId, extra_data={"field": "waitUntil"})
        return _err("VALIDATION_ERROR", "waitUntil must be one of: load, domcontentloaded, networkidle, commit", field="waitUntil")

    if timeoutMs is not None:
        if not isinstance(timeoutMs, (int, float)) or timeoutMs <= 0:
            _audit("VALIDATION_ERROR", "Invalid timeoutMs", session_id=sessionId, extra_data={"field": "timeoutMs"})
            return _err("VALIDATION_ERROR", "timeoutMs must be a positive number (milliseconds)", field="timeoutMs")
        if timeoutMs > 300000:
            _audit("VALIDATION_ERROR", "timeoutMs too large", session_id=sessionId, extra_data={"field": "timeoutMs"})
            return _err("VALIDATION_ERROR", "timeoutMs must be <= 300000", field="timeoutMs")

    job_id_effective = None
    job_row = None
    if jobId is not None:
        if not isinstance(jobId, str) or not jobId.strip():
            _audit("VALIDATION_ERROR", "Invalid jobId type", session_id=sessionId, extra_data={"field": "jobId"})
            return _err("VALIDATION_ERROR", "`jobId` is invalid.", field="jobId")
        if job_pat.match(jobId):
            job_row = next((j for j in jobs if isinstance(j, dict) and j.get("id") == jobId), None)
            if not job_row:
                _audit("NOT_FOUND", "Job not found", session_id=sessionId, job_id=jobId)
                return _err("NOT_FOUND", "Job not found", jobId=jobId)
            if job_row.get("session_id") not in (None, sessionId):
                _audit("CONFLICT", "Job does not belong to session", session_id=sessionId, job_id=jobId)
                return _err("CONFLICT", "Job does not belong to the provided session", jobId=jobId, sessionId=sessionId)
            if job_row.get("status") == "cancelled":
                _audit("INVALID_TRANSITION", "Job cancelled", session_id=sessionId, job_id=jobId)
                return _err("INVALID_TRANSITION", "Job is cancelled; cannot record new navigation events.", jobId=jobId)
            job_id_effective = jobId

    sess = next((s for s in sessions if isinstance(s, dict) and s.get("id") == sessionId), None)
    if not sess:
        _audit("NOT_FOUND", "Session not found", session_id=sessionId, job_id=job_id_effective)
        return _err("NOT_FOUND", "Session not found", sessionId=sessionId)

    if sess.get("status") != "active":
        _audit("INVALID_TRANSITION", "Session not active", session_id=sessionId, job_id=job_id_effective, extra_data={"sessionStatus": sess.get("status")})
        return _err("INVALID_TRANSITION", "Session is not active; cannot navigate", sessionStatus=sess.get("status"))

    eff_wait = waitUntil or sess.get("default_wait_until") or "load"
    eff_timeout = int(timeoutMs) if timeoutMs is not None else int(sess.get("default_timeout_ms") or 30000)

    prev_url = sess.get("current_url") or sess.get("start_url")
    sess["updated_at"] = now
    _save("sessions.json", sessions)

    result = {
        "sessionId": sessionId,
        "jobId": job_id_effective,
        "action": "go_forward",
        "waitUntil": eff_wait,
        "timeoutMs": eff_timeout,
        "fromUrl": prev_url,
        "finalUrl": sess.get("current_url") or prev_url,
        "timing": {"started_at": now, "finished_at": now, "duration_ms": int((time.time() - t0) * 1000)},
    }

    _audit("ok", "Navigated forward", session_id=sessionId, job_id=job_id_effective, extra_data=result)
    return result

def playwright_press_key(key, selector=None, **_extra):
    import json, os, datetime, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0316000" if __import__("os").path.isdir("./environment_mix/0316000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    if not isinstance(key, str) or not key.strip():
        return _err("VALIDATION_ERROR", "key is required and must be a non-empty string", field="key")
    if selector is not None and (not isinstance(selector, str) or not selector.strip()):
        return _err("VALIDATION_ERROR", "selector, when provided, must be a non-empty string", field="selector")

    sessions = _load("sessions.json")
    event_logs = _load("event_logs.json")

    # Ambient auth/context: pick an active session to attach action to (must exist to be "active page")
    sess = next((s for s in sessions if s.get("status") == "active"), None)
    if not sess:
        return _err("UNAUTHORIZED", "No active session available for Playwright action")

    # If selector is provided, we can't truly query DOM offline; treat empty selector as validation error only.
    # For NOT_FOUND behavior: if selector references impossible sentinel, return NOT_FOUND (deterministic).
    if selector is not None and selector.strip() in ("__missing__", ":not(*)"):
        return _err("NOT_FOUND", "Element not found for selector", selector=selector)

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ts = int(datetime.datetime.utcnow().timestamp() * 1000)
        rnd = random.getrandbits(80)
        x = (ts << 80) | rnd
        out = []
        for _ in range(26):
            out.append(alphabet[x & 31])
            x >>= 5
        return prefix + "".join(reversed(out))

    evt_id = _gen_id("vuda_evt_")
    duration_ms = 30
    # Record as playwright_action
    event_logs.append({
        "id": evt_id,
        "session_id": sess.get("id"),
        "job_id": None,
        "event_type": "playwright_action",
        "severity": "info",
        "message": "press_key recorded",
        "data": {
            "action": "press_key",
            "key": key,
            "selector": selector,
            "focused": bool(selector),
            "duration_ms": duration_ms
        },
        "occurred_at": now,
        "created_at": now,
        "updated_at": now
    })
    _save("event_logs.json", event_logs)

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "sessionId": sess.get("id"),
        "action": "press_key",
        "key": key,
        "selector": selector,
        "focused": bool(selector),
        "signals": {"consoleErrors": 0},
        "timing": {"durationMs": duration_ms, "apiLatencyMs": latency_ms},
        "eventLogId": evt_id
    }

