def ui_workflow_validator(startUrl, taskDescription, steps, captureScreenshots=None, device=None, **_extra):
    import json, os, datetime, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0316000" if __import__("os").path.isdir("./environment_mix/0316000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    sessions = _load("sessions.json")
    jobs = _load("jobs.json")
    job_steps = _load("job_steps.json")
    artifacts = _load("artifacts.json")
    event_logs = _load("event_logs.json")

    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return prefix + "".join(random.choice(alphabet) for _ in range(20))

    def _audit(status_code, message, session_id=None, job_id=None, extra_data=None, severity=None):
        nonlocal event_logs
        sev = severity
        if sev is None:
            sev = "info" if status_code in ("ok", "succeeded") else "error"
        event_logs.append({
            "id": _new_id("vuda_evt_"),
            "session_id": session_id,
            "job_id": job_id,
            "event_type": "playwright_action",
            "severity": sev,
            "message": message,
            "data": {"endpoint": "ui_workflow_validator", "status": status_code, "latency_ms": int((time.time() - t0) * 1000), **(extra_data or {})},
            "occurred_at": now,
            "created_at": now,
            "updated_at": now
        })
        _save("event_logs.json", event_logs)

    # Validate top-level input per schema
    if not isinstance(startUrl, str) or not startUrl.strip():
        _audit("VALIDATION_ERROR", "Invalid startUrl", extra_data={"field": "startUrl"})
        return _err("VALIDATION_ERROR", "startUrl must be a non-empty string.", field="startUrl")
    if not isinstance(taskDescription, str) or not taskDescription.strip():
        _audit("VALIDATION_ERROR", "Invalid taskDescription", extra_data={"field": "taskDescription"})
        return _err("VALIDATION_ERROR", "taskDescription must be a non-empty string.", field="taskDescription")
    if not isinstance(steps, list) or len(steps) < 1:
        _audit("VALIDATION_ERROR", "Invalid steps", extra_data={"field": "steps"})
        return _err("VALIDATION_ERROR", "steps must be an array with at least 1 item.", field="steps")

    if captureScreenshots is None:
        captureScreenshots = "failure"
    if not isinstance(captureScreenshots, str) or captureScreenshots not in ("all", "failure", "none"):
        _audit("VALIDATION_ERROR", "Invalid captureScreenshots", extra_data={"field": "captureScreenshots"})
        return _err("VALIDATION_ERROR", "captureScreenshots must be one of: all, failure, none.", field="captureScreenshots")

    if device is not None and (not isinstance(device, str) or not device.strip()):
        _audit("VALIDATION_ERROR", "Invalid device", extra_data={"field": "device"})
        return _err("VALIDATION_ERROR", "device must be a non-empty string when provided.", field="device")

    allowed_actions = {"navigate", "click", "fill", "select", "hover", "wait", "evaluate", "screenshot", "verifyText", "verifyElementVisible", "verifyElementNotVisible", "verifyUrl"}

    def _get_field(step, k):
        if not isinstance(step, dict):
            return None
        return step.get(k)

    # Validate steps with relaxed rule: navigate may omit url (use startUrl), and verifyUrl may use url or value.
    normalized_steps = []
    for i, st in enumerate(steps):
        if not isinstance(st, dict):
            _audit("VALIDATION_ERROR", "Step must be object", extra_data={"field": f"steps[{i}]"})
            return _err("VALIDATION_ERROR", f"steps[{i}] must be an object.", field=f"steps[{i}]")
        desc = _get_field(st, "description")
        action = _get_field(st, "action")
        if not isinstance(desc, str) or not desc.strip():
            _audit("VALIDATION_ERROR", "Missing step description", extra_data={"field": f"steps[{i}].description"})
            return _err("VALIDATION_ERROR", f"steps[{i}].description is required.", field=f"steps[{i}].description")
        if not isinstance(action, str) or action not in allowed_actions:
            _audit("VALIDATION_ERROR", "Invalid step action", extra_data={"field": f"steps[{i}].action"})
            return _err("VALIDATION_ERROR", f"steps[{i}].action must be one of the supported actions.", field=f"steps[{i}].action")

        selector = _get_field(st, "selector")
        value = _get_field(st, "value")
        url = _get_field(st, "url")
        script = _get_field(st, "script")
        is_opt = _get_field(st, "isOptional")
        if is_opt is None:
            is_opt = False
        if not isinstance(is_opt, bool):
            _audit("VALIDATION_ERROR", "Invalid isOptional", extra_data={"field": f"steps[{i}].isOptional"})
            return _err("VALIDATION_ERROR", f"steps[{i}].isOptional must be boolean.", field=f"steps[{i}].isOptional")

        # Required per-action fields (business rule), with navigate relaxed to allow omission
        if action in ("click", "hover", "verifyElementVisible", "verifyElementNotVisible"):
            if not isinstance(selector, str) or not selector.strip():
                _audit("VALIDATION_ERROR", "selector required", extra_data={"field": f"steps[{i}].selector"})
                return _err("VALIDATION_ERROR", f"steps[{i}] action '{action}' requires selector.", field=f"steps[{i}].selector")
        if action in ("fill", "select"):
            if not isinstance(selector, str) or not selector.strip() or not isinstance(value, str):
                _audit("VALIDATION_ERROR", "fill/select require selector+value", extra_data={"field": f"steps[{i}]"})
                return _err("VALIDATION_ERROR", f"steps[{i}] action '{action}' requires selector and value.", field=f"steps[{i}]")
        if action == "evaluate":
            if not isinstance(script, str) or not script.strip():
                _audit("VALIDATION_ERROR", "evaluate requires script", extra_data={"field": f"steps[{i}].script"})
                return _err("VALIDATION_ERROR", f"steps[{i}] action 'evaluate' requires script.", field=f"steps[{i}].script")
        if action == "navigate":
            # If url omitted, default to startUrl (accept and persist)
            if url is not None and (not isinstance(url, str) or not url.strip()):
                _audit("VALIDATION_ERROR", "Invalid url", extra_data={"field": f"steps[{i}].url"})
                return _err("VALIDATION_ERROR", f"steps[{i}].url must be a non-empty string when provided.", field=f"steps[{i}].url")
        if action == "verifyUrl":
            if (url is None or (isinstance(url, str) and not url.strip())) and (value is None or (isinstance(value, str) and not value.strip())):
                _audit("VALIDATION_ERROR", "verifyUrl requires url or value", extra_data={"field": f"steps[{i}]"})
                return _err("VALIDATION_ERROR", f"steps[{i}] action 'verifyUrl' requires url or value.", field=f"steps[{i}]")

        normalized_steps.append({
            "description": desc,
            "action": action,
            "selector": selector,
            "value": value,
            "url": url,
            "script": script,
            "isOptional": is_opt
        })

    # Resolve or create active session
    active = [s for s in sessions if isinstance(s, dict) and s.get("status") == "active"]
    if active:
        active.sort(key=lambda r: (r.get("updated_at") or "", r.get("created_at") or ""), reverse=True)
        session = active[0]
    else:
        session = {
            "id": _new_id("vuda_sess_"),
            "status": "active",
            "origin_tool": "ui_workflow_validator",
            "start_url": startUrl,
            "current_url": startUrl,
            "device": device,
            "default_wait_until": "load",
            "default_timeout_ms": 30000,
            "console_capture_enabled": True,
            "element_mapping_enabled": True,
            "stability_wait_ms": 0,
            "created_at": now,
            "updated_at": now
        }
        sessions.append(session)
        _save("sessions.json", sessions)

    # Create job (queued -> running -> succeeded)
    job_id = _new_id("vuda_job_")
    job = {
        "id": job_id,
        "session_id": session.get("id"),
        "tool_name": "ui_workflow_validator",
        "status": "running",
        "input": {
            "startUrl": startUrl,
            "taskDescription": taskDescription,
            "steps": normalized_steps,
            "captureScreenshots": captureScreenshots,
            "device": device
        },
        "normalized_target_url": startUrl if startUrl.startswith("http") else None,
        "started_at": now,
        "finished_at": None,
        "error_message": None,
        "output_format": None,
        "summary": None,
        "created_at": now,
        "updated_at": now
    }
    jobs.append(job)
    _save("jobs.json", jobs)

    # Create job_steps contiguous
    created_steps = []
    for idx, st in enumerate(normalized_steps):
        step_id = _new_id("vuda_step_")
        js = {
            "id": step_id,
            "job_id": job_id,
            "step_index": idx,
            "description": st.get("description"),
            "action": st.get("action"),
            "selector": st.get("selector"),
            "value": st.get("value"),
            "url": st.get("url"),
            "script": st.get("script"),
            "is_optional": bool(st.get("isOptional", False)),
            "status": "passed",  # offline: assume pass
            "started_at": now,
            "finished_at": now,
            "error_message": None,
            "screenshot_artifact_id": None,
            "created_at": now,
            "updated_at": now
        }
        # ensure unique(job_id, step_index)
        if any(r for r in job_steps if isinstance(r, dict) and r.get("job_id") == job_id and r.get("step_index") == idx):
            _audit("CONFLICT", "Duplicate step_index", session_id=session.get("id"), job_id=job_id, extra_data={"step_index": idx})
            return _err("CONFLICT", "Duplicate step_index for job.", jobId=job_id, step_index=idx)
        job_steps.append(js)
        created_steps.append(js)

        # Screenshot capture rule
        should_capture = (captureScreenshots == "all")
        if should_capture:
            art_id = _new_id("vuda_art_")
            art = {
                "id": art_id,
                "session_id": session.get("id"),
                "job_id": job_id,
                "kind": "screenshot",
                "name": f"step_{idx}",
                "source_url": session.get("current_url") or startUrl,
                "selector": st.get("selector"),
                "full_page": True,
                "mime_type": "image/png",
                "byte_size": None,
                "storage_uri": None,
                "content": {"step_index": idx, "capture": "workflow"},
                "created_at": now,
                "updated_at": now
            }
            artifacts.append(art)
            js["screenshot_artifact_id"] = art_id
            js["updated_at"] = now

        # Apply navigate effect on session current_url when possible
        if st.get("action") == "navigate":
            nav_to = st.get("url") or startUrl
            if isinstance(nav_to, str) and nav_to.strip():
                session["current_url"] = nav_to

    _save("job_steps.json", job_steps)
    if artifacts:
        _save("artifacts.json", artifacts)

    # Finish job
    job["status"] = "succeeded"
    job["finished_at"] = now
    job["updated_at"] = now
    job["summary"] = {"steps_total": len(normalized_steps), "steps_passed": len(normalized_steps), "steps_failed": 0}
    _save("jobs.json", jobs)

    session["updated_at"] = now
    session["start_url"] = session.get("start_url") or startUrl
    _save("sessions.json", sessions)

    _audit("ok", "Workflow completed", session_id=session.get("id"), job_id=job_id, extra_data={"steps": len(normalized_steps), "finalUrl": session.get("current_url")})

    return {
        "sessionId": session.get("id"),
        "jobId": job_id,
        "status": "succeeded",
        "startUrl": startUrl,
        "finalUrl": session.get("current_url"),
        "taskDescription": taskDescription,
        "captureScreenshots": captureScreenshots,
        "device": device,
        "steps": created_steps,
        "summary": job.get("summary")
    }

