    t0 = datetime.datetime.utcnow()
    now = t0.replace(microsecond=0).isoformat() + "Z"

    # resolve active session (optional scoping)
    sessions = _load("sessions.json")
    active = [s for s in sessions if isinstance(s, dict) and s.get("status") == "active"]
    session_id = None
    if active:
        active.sort(key=lambda r: (r.get("updated_at") or "", r.get("created_at") or ""), reverse=True)
        session_id = active[0].get("id")

    def _log(status, message, severity="info", data=None):
        latency_ms = int((datetime.datetime.utcnow() - t0).total_seconds() * 1000)
        logs = _load("event_logs.json")
        logs.append({
            "id": "evt_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
            "session_id": session_id,
            "job_id": None,
            "event_type": "tunnel" if action in ("store", "retrieve") else "playwright_action",
            "severity": severity,
            "message": message,
            "data": {"endpoint": "tunnel_helper", "status": status, "latency_ms": latency_ms, **(data or {})},
            "occurred_at": now,
            "created_at": now,
            "updated_at": now
        })
        _save("event_logs.json", logs)

    # validate
    if action not in ("guide", "store", "retrieve"):
        _log("error", "validation error: unsupported action", severity="error")
        return _err("VALIDATION_ERROR", "action must be one of: guide, store, retrieve")
    if not isinstance(localPort, (int, float)) or isinstance(localPort, bool):
        _log("error", "validation error: localPort type", severity="error")
        return _err("VALIDATION_ERROR", "localPort must be a number")
    try:
        lp = int(localPort)
    except Exception:
        _log("error", "validation error: localPort not coercible to int", severity="error")
        return _err("VALIDATION_ERROR", "localPort must be an integer port number")
    if lp < 1 or lp > 65535:
        _log("error", "validation error: localPort out of range", severity="error")
        return _err("VALIDATION_ERROR", "localPort must be between 1 and 65535")

    if action == "guide":
        _log("ok", "returned guide instructions")
        return {
            "action": "guide",
            "localPort": lp,
            "instructions": [
                "1) Start your local server on the specified localPort.",
                "2) Run a tunnel provider (e.g., cloudflared, ngrok) to expose http://localhost:<localPort>.",
                "3) Copy the public tunnel URL (https://...).",
                "4) Call tunnel_helper with action='store' to save it for later retrieve."
            ],
            "examples": {
                "cloudflared": f"cloudflared tunnel --url http://localhost:{lp}",
                "ngrok": f"ngrok http {lp}"
            }
        }

    if action == "store":
        if not isinstance(tunnelUrl, str) or not tunnelUrl.strip():
            _log("error", "validation error: tunnelUrl required for store", severity="error")
            return _err("VALIDATION_ERROR", "tunnelUrl is required for action='store'")
        # Store as tunnel event log
        logs = _load("event_logs.json")
        evt_id = "evt_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f")
        evt = {
            "id": evt_id,
            "session_id": session_id,
            "job_id": None,
            "event_type": "tunnel",
            "severity": "info",
            "message": "Stored tunnel URL",
            "data": {"localPort": lp, "tunnelUrl": tunnelUrl.strip(), "action": "store"},
            "occurred_at": now,
            "created_at": now,
            "updated_at": now
        }
        logs.append(evt)
        _save("event_logs.json", logs)
        _log("ok", "tunnel mapping stored", data={"localPort": lp})
        return {"action": "store", "localPort": lp, "tunnelUrl": tunnelUrl.strip(), "event_id": evt_id}

    # retrieve
    logs = _load("event_logs.json")
    candidates = []
    for e in logs:
        if not isinstance(e, dict): 
            continue
        if e.get("event_type") != "tunnel":
            continue
        d = e.get("data") or {}
        if not isinstance(d, dict):
            continue
        if d.get("localPort") != lp:
            continue
        # optionally scoped by session if available: prefer same-session entries
        candidates.append(e)

    if not candidates:
        _log("error", "not found: no stored tunnelUrl for localPort", severity="error", data={"localPort": lp})
        return _err("NOT_FOUND", "No stored tunnelUrl for the requested localPort", localPort=lp)

    # prefer latest in same session, else latest overall
    same_session = [c for c in candidates if session_id is not None and c.get("session_id") == session_id]
    pool = same_session if same_session else candidates
    pool.sort(key=lambda r: (r.get("created_at") or "", r.get("occurred_at") or ""), reverse=True)
    chosen = pool[0]
    d = chosen.get("data") or {}
    tunnel_url = d.get("tunnelUrl")

    if not tunnel_url:
        _log("error", "not found: latest tunnel event missing tunnelUrl", severity="error", data={"localPort": lp})
        return _err("NOT_FOUND", "No stored tunnelUrl found for the requested localPort", localPort=lp)

    _log("ok", "tunnel mapping retrieved", data={"localPort": lp})
    return {"action": "retrieve", "localPort": lp, "tunnelUrl": tunnel_url, "event_id": chosen.get("id")}

def debug_memory(action, key=None, value=None, category=None, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0316000" if __import__("os").path.isdir("./environment_mix/0316000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = datetime.datetime.utcnow()
    now = t0.replace(microsecond=0).isoformat() + "Z"

    # resolve active session (optional scoping)
    sessions = _load("sessions.json")
    active = [s for s in sessions if isinstance(s, dict) and s.get("status") == "active"]
    session_id = None
    if active:
        active.sort(key=lambda r: (r.get("updated_at") or "", r.get("created_at") or ""), reverse=True)
        session_id = active[0].get("id")

    def _log(status, message, severity="info", data=None):
        latency_ms = int((datetime.datetime.utcnow() - t0).total_seconds() * 1000)
        logs = _load("event_logs.json")
        logs.append({
            "id": "evt_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
            "session_id": session_id,
            "job_id": None,
            "event_type": "memory",
            "severity": severity,
            "message": message,
            "data": {"endpoint": "debug_memory", "status": status, "latency_ms": latency_ms, **(data or {})},
            "occurred_at": now,
            "created_at": now,
            "updated_at": now
        })
        _save("event_logs.json", logs)

    allowed_actions = ("save", "retrieve", "list", "clear")
    allowed_categories = ("env", "urls", "selectors", "issues", "fixes", "general")

    if action not in allowed_actions:
        _log("error", "validation error: invalid action", severity="error")
        return _err("VALIDATION_ERROR", "action must be one of: save, retrieve, list, clear")
    if category is not None and category not in allowed_categories:
        _log("error", "validation error: invalid category", severity="error")
        return _err("VALIDATION_ERROR", "category must be one of: env, urls, selectors, issues, fixes, general")

    logs = _load("event_logs.json")

    def _iter_memory_events():
        for e in logs:
            if not isinstance(e, dict):
                continue
            if e.get("event_type") != "memory":
                continue
            d = e.get("data")
            if not isinstance(d, dict):
                continue
            yield e, d

    if action == "save":
        if not isinstance(key, str) or not key.strip():
            _log("error", "validation error: key required for save", severity="error")
            return _err("VALIDATION_ERROR", "key is required for action='save'")
        if value is None or not isinstance(value, (dict, list, str, int, float, bool)) and value is not None:
            # schema says object; accept any JSON-like, but require not None
            pass
        if value is None:
            _log("error", "validation error: value required for save", severity="error")
            return _err("VALIDATION_ERROR", "value is required for action='save'")

        evt_id = "evt_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f")
        evt = {
            "id": evt_id,
            "session_id": session_id,
            "job_id": None,
            "event_type": "memory",
            "severity": "info",
            "message": "Saved memory item",
            "data": {"action": "save", "key": key.strip(), "category": category or "general", "value": value},
            "occurred_at": now,
            "created_at": now,
            "updated_at": now
        }
        logs.append(evt)
        _save("event_logs.json", logs)
        _log("ok", "memory saved", data={"key": key.strip(), "category": category or "general"})
        return {"action": "save", "key": key.strip(), "category": category or "general", "value": value, "event_id": evt_id}

    if action == "retrieve":
        if not isinstance(key, str) or not key.strip():
            _log("error", "validation error: key required for retrieve", severity="error")
            return _err("VALIDATION_ERROR", "key is required for action='retrieve'")
        k = key.strip()
        candidates = []
        for e, d in _iter_memory_events():
            if d.get("action") != "save":
                continue
            if d.get("key") != k:
                continue
            if category is not None and d.get("category") != category:
                continue
            candidates.append((e, d))
        if not candidates:
            _log("error", "not found: memory key", severity="error", data={"key": k, "category": category})
            return _err("NOT_FOUND", "No saved memory found for the requested key", key=k, category=category)
        candidates.sort(key=lambda ed: (ed[0].get("created_at") or "", ed[0].get("occurred_at") or ""), reverse=True)
        e, d = candidates[0]
        _log("ok", "memory retrieved", data={"key": k, "category": d.get("category")})
        return {"action": "retrieve", "key": k, "category": d.get("category"), "value": d.get("value"), "event_id": e.get("id")}

    if action == "list":
        # return distinct keys (optionally by category), with their latest value metadata
        latest_by_key = {}
        for e, d in _iter_memory_events():
            if d.get("action") != "save":
                continue
            if category is not None and d.get("category") != category:
                continue
            k = d.get("key")
            if not isinstance(k, str) or not k.strip():
                continue
            prev = latest_by_key.get(k)
            if prev is None:
                latest_by_key[k] = (e, d)
            else:
                if (e.get("created_at") or "") > (prev[0].get("created_at") or ""):
                    latest_by_key[k] = (e, d)

        items = []
        for k, (e, d) in latest_by_key.items():
            items.append({
                "key": k,
                "category": d.get("category"),
                "value": d.get("value"),
                "event_id": e.get("id"),
                "saved_at": e.get("created_at") or e.get("occurred_at")
            })
        items.sort(key=lambda it: it.get("key") or "")
        _log("ok", "memory listed", data={"count": len(items), "category": category})
        return {"action": "list", "category": category, "items": items, "count": len(items)}

    # clear
    # scope: by key and/or category; if neither provided, clear all memory events
    to_keep = []
    removed = 0
    for e in logs:
        if not isinstance(e, dict) or e.get("event_type") != "memory":
            to_keep.append(e)
            continue
        d = e.get("data") or {}
        if not isinstance(d, dict):
            # treat as memory event, clearable
            match = True
        else:
            match = True
            if key is not None:
                if not (isinstance(key, str) and key.strip()):
                    _log("error", "validation error: key must be non-empty string when provided", severity="error")
                    return _err("VALIDATION_ERROR", "key must be a non-empty string when provided")
                match = match and (d.get("key") == key.strip())
            if category is not None:
                match = match and (d.get("category") == category)
        if match:
            removed += 1
        else:
            to_keep.append(e)

    if removed == 0:
        _log("error", "not found: no memory events to clear", severity="error", data={"key": key, "category": category})
        return _err("NOT_FOUND", "No memory items matched the clear criteria", key=key, category=category)

    _save("event_logs.json", to_keep)
    _log("ok", "memory cleared", data={"removed": removed, "key": key, "category": category})
    return {"action": "clear", "key": key, "category": category, "removed": removed}

def sitemap_crawler(url, maxDepth=None, includeText=None, sameDomainOnly=None, outputFormat=None, **_extra):
    import json, os, datetime, time, re
    from urllib.parse import urlparse

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0316000" if __import__("os").path.isdir("./environment_mix/0316000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    jobs = _load("jobs.json")
    artifacts = _load("artifacts.json")
    event_logs = _load("event_logs.json")

    def _log_job(status, job_id=None, message=None):
        nonlocal event_logs
        try:
            eid = f"evt_{int(time.time()*1000)}_{len(event_logs)+1}"
            event_logs.append({
                "id": eid,
                "session_id": None,
                "job_id": job_id,
                "event_type": "crawler",
                "severity": "info",
                "message": message or ("sitemap_crawler " + status),
                "data": {"tool": "sitemap_crawler", "status": status},
                "occurred_at": now,
                "created_at": now,
                "updated_at": now
            })
            _save("event_logs.json", event_logs)
        except Exception:
            # event log write should not break the call
            pass

    # Validate inputs
    if not isinstance(url, str) or not url.strip():
        _log_job("failed", None, "VALIDATION_ERROR: url missing/invalid")
        return _err("VALIDATION_ERROR", "url is required and must be a non-empty string")
    url = url.strip()
    pu = urlparse(url)
    if pu.scheme not in ("http", "https") or not pu.netloc:
        _log_job("failed", None, "VALIDATION_ERROR: url must be http(s)")
        return _err("VALIDATION_ERROR", "url must be a valid http(s) URL")

    if maxDepth is None:
        maxDepth = 3
    if isinstance(maxDepth, bool) or not isinstance(maxDepth, (int, float)):
        _log_job("failed", None, "VALIDATION_ERROR: maxDepth type")
        return _err("VALIDATION_ERROR", "maxDepth must be a number")
    if int(maxDepth) != maxDepth:
        # allow floats that are integer-like
        if not (isinstance(maxDepth, float) and abs(maxDepth - int(maxDepth)) < 1e-9):
            _log_job("failed", None, "VALIDATION_ERROR: maxDepth must be integer")
            return _err("VALIDATION_ERROR", "maxDepth must be an integer between 1 and 10")
    maxDepth = int(maxDepth)
    if maxDepth < 1 or maxDepth > 10:
        _log_job("failed", None, "VALIDATION_ERROR: maxDepth range")
        return _err("VALIDATION_ERROR", "maxDepth must be between 1 and 10")

    if includeText is None:
        includeText = True
    if not isinstance(includeText, bool):
        _log_job("failed", None, "VALIDATION_ERROR: includeText type")
        return _err("VALIDATION_ERROR", "includeText must be boolean")

    if sameDomainOnly is None:
        sameDomainOnly = True
    if not isinstance(sameDomainOnly, bool):
        _log_job("failed", None, "VALIDATION_ERROR: sameDomainOnly type")
        return _err("VALIDATION_ERROR", "sameDomainOnly must be boolean")

    if outputFormat is None:
        outputFormat = "markdown"
    if outputFormat not in ("json", "markdown", "text"):
        _log_job("failed", None, "VALIDATION_ERROR: outputFormat enum")
        return _err("VALIDATION_ERROR", "outputFormat must be one of: json, markdown, text")

    # Create job row (queued -> running -> succeeded/failed)
    def _new_id(prefix, existing):
        return f"{prefix}_{int(time.time()*1000)}_{len(existing)+1}"

    job_id = _new_id("job", jobs)
    job_now = now
    job = {
        "id": job_id,
        "session_id": None,
        "tool_name": "sitemap_crawler",
        "status": "queued",
        "input": {
            "url": url,
            "maxDepth": maxDepth,
            "includeText": includeText,
            "sameDomainOnly": sameDomainOnly,
            "outputFormat": outputFormat
        },
        "normalized_target_url": url,
        "started_at": None,
        "finished_at": None,
        "error_message": None,
        "output_format": outputFormat,
        "summary": None,
        "created_at": job_now,
        "updated_at": job_now
    }
    jobs.append(job)
    _save("jobs.json", jobs)
    _log_job("queued", job_id, "job queued")

    # Transition queued -> running
    job["status"] = "running"
    job["started_at"] = now
    job["updated_at"] = now
    _save("jobs.json", jobs)
    _log_job("running", job_id, "job running")

    # Real crawling is not possible offline; generate sitemap based on observable stored data.
    # We approximate by using existing artifacts/event_logs for the same domain and the start url itself.
    base_host = pu.netloc.lower()

    def _same_domain(u):
        try:
            p = urlparse(u)
            return p.scheme in ("http", "https") and p.netloc and p.netloc.lower() == base_host
        except Exception:
            return False

    urls = []
    urls_set = set()

    def _add(u, depth, source=None):
        if not isinstance(u, str) or not u:
            return
        try:
            p = urlparse(u)
        except Exception:
            return
        if p.scheme not in ("http", "https") or not p.netloc:
            return
        if sameDomainOnly and p.netloc.lower() != base_host:
            return
        key = u
        if key in urls_set:
            return
        urls_set.add(key)
        urls.append({"url": u, "depth": depth, "source": source})

    _add(url, 0, None)

    # Candidate URLs from artifacts/source_url and sessions current_url/start_url
    sessions = _load("sessions.json")
    for s in sessions:
        su = s.get("start_url")
        cu = s.get("current_url")
        if isinstance(su, str):
            if (not sameDomainOnly) or _same_domain(su):
                _add(su, 1, "sessions.start_url")
        if isinstance(cu, str):
            if (not sameDomainOnly) or _same_domain(cu):
                _add(cu, 1, "sessions.current_url")

    for a in artifacts:
        su = a.get("source_url")
        if isinstance(su, str):
            if (not sameDomainOnly) or _same_domain(su):
                _add(su, 1, "artifacts.source_url")

    # Candidate URLs from crawler/api events payloads
    for e in event_logs:
        et = e.get("event_type")
        data = e.get("data") or {}
        if et in ("crawler", "api_endpoint_result", "playwright_action"):
            for k in ("url", "pageUrl", "targetUrl", "source_url"):
                u = data.get(k)
                if isinstance(u, str):
                    if (not sameDomainOnly) or _same_domain(u):
                        _add(u, 1, f"event_logs.data.{k}")
            out_links = data.get("out_links")
            if isinstance(out_links, list):
                for u in out_links:
                    if isinstance(u, str):
                        if (not sameDomainOnly) or _same_domain(u):
                            _add(u, 2, "event_logs.data.out_links")

    # Cap depth
    nodes = []
    for item in urls:
        d = item["depth"]
        if d <= maxDepth:
            nodes.append(item)

    # Include "text" by reusing any stored visible_text/visible_html artifacts content when available
    text_by_url = {}
    if includeText:
        for a in artifacts:
            if a.get("kind") in ("visible_text", "visible_html"):
                su = a.get("source_url")
                if isinstance(su, str) and ((not sameDomainOnly) or _same_domain(su)):
                    content = a.get("content")
                    if isinstance(content, dict):
                        txt = content.get("text") or content.get("visibleText") or content.get("snippet")
                        if isinstance(txt, str) and txt.strip():
                            text_by_url.setdefault(su, txt.strip())
                    elif isinstance(content, str) and content.strip():
                        text_by_url.setdefault(su, content.strip())

    sitemap_obj = {
        "startUrl": url,
        "maxDepth": maxDepth,
        "sameDomainOnly": sameDomainOnly,
        "includeText": includeText,
        "pages": []
    }
    for n in nodes:
        page = {"url": n["url"], "depth": n["depth"]}
        if includeText:
            page["text"] = text_by_url.get(n["url"])
        sitemap_obj["pages"].append(page)

    # Render output
    if outputFormat == "json":
        rendered = sitemap_obj
        mime = "application/json"
    elif outputFormat == "markdown":
        lines = [f"# Sitemap", f"- Start: {url}", f"- Max depth: {maxDepth}", f"- Same domain only: {sameDomainOnly}", ""]
        for p in sitemap_obj["pages"]:
            lines.append(f"- [{p['url']}]({p['url']}) (depth {p['depth']})")
            if includeText and p.get("text"):
                snippet = p["text"]
                snippet = re.sub(r"\s+", " ", snippet).strip()
                if len(snippet) > 240:
                    snippet = snippet[:240] + "…"
                lines.append(f"  - Text: {snippet}")
        rendered = "\n".join(lines).strip() + "\n"
        mime = "text/markdown"
    else:  # text
        lines = [f"Sitemap", f"Start: {url}", f"MaxDepth: {maxDepth}", f"SameDomainOnly: {sameDomainOnly}", ""]
        for p in sitemap_obj["pages"]:
            lines.append(f"{p['url']} (depth {p['depth']})")
            if includeText and p.get("text"):
                snippet = re.sub(r"\s+", " ", p["text"]).strip()
                if len(snippet) > 240:
                    snippet = snippet[:240] + "…"
                lines.append(f"  Text: {snippet}")
        rendered = "\n".join(lines).strip() + "\n"
        mime = "text/plain"

    # Create sitemap artifact
    art_id = _new_id("art", artifacts)
    art_now = now
    artifact = {
        "id": art_id,
        "session_id": None,
        "job_id": job_id,
        "kind": "sitemap",
        "name": None,
        "source_url": url,
        "selector": None,
        "full_page": None,
        "mime_type": mime,
        "byte_size": None,
        "storage_uri": None,
        "content": rendered if outputFormat == "json" else {"format": outputFormat, "body": rendered},
        "created_at": art_now,
        "updated_at": art_now
    }
    artifacts.append(artifact)
    _save("artifacts.json", artifacts)

    # Finish job (running -> succeeded)
    job["status"] = "succeeded"
    job["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    job["updated_at"] = job["finished_at"]
    job["summary"] = {"pages": len(sitemap_obj["pages"]), "artifact_id": art_id, "outputFormat": outputFormat}
    _save("jobs.json", jobs)
    _log_job("succeeded", job_id, "job succeeded")

    return {
        "job": job,
        "artifact": artifact,
        "result": sitemap_obj if outputFormat == "json" else {"outputFormat": outputFormat, "mime_type": mime, "body": rendered},
        "meta": {"latency_ms": int((time.time() - t0) * 1000)}
    }

def create_session(origin_tool, start_url, device=None, default_wait_until=None, default_timeout_ms=None, console_capture_enabled=None, element_mapping_enabled=None, stability_wait_ms=None, **_extra):
    import json, os, datetime, time
    from urllib.parse import urlparse

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0316000" if __import__("os").path.isdir("./environment_mix/0316000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    sessions = _load("sessions.json")
    event_logs = _load("event_logs.json")

    def _audit(status, message):
        nonlocal event_logs
        try:
            eid = f"evt_{int(time.time()*1000)}_{len(event_logs)+1}"
            event_logs.append({
                "id": eid,
                "session_id": None,
                "job_id": None,
                "event_type": "playwright_action",
                "severity": "info" if status == "ok" else "error",
                "message": message,
                "data": {"endpoint": "create_session", "status": status},
                "occurred_at": now,
                "created_at": now,
                "updated_at": now
            })
            _save("event_logs.json", event_logs)
        except Exception:
            pass

    # Validate
    if not isinstance(origin_tool, str) or not origin_tool.strip():
        _audit("error", "VALIDATION_ERROR: origin_tool")
        return _err("VALIDATION_ERROR", "origin_tool is required and must be a non-empty string")
    if not isinstance(start_url, str) or not start_url.strip():
        _audit("error", "VALIDATION_ERROR: start_url")
        return _err("VALIDATION_ERROR", "start_url is required and must be a non-empty string")
    start_url = start_url.strip()
    pu = urlparse(start_url)
    if pu.scheme not in ("http", "https") or not pu.netloc:
        _audit("error", "VALIDATION_ERROR: start_url must be http(s)")
        return _err("VALIDATION_ERROR", "start_url must be a valid http(s) URL")

    if default_wait_until is None:
        default_wait_until = "networkidle"
    if default_wait_until not in ("load", "domcontentloaded", "networkidle"):
        _audit("error", "VALIDATION_ERROR: default_wait_until enum")
        return _err("VALIDATION_ERROR", "default_wait_until must be one of: load, domcontentloaded, networkidle")

    if default_timeout_ms is None:
        default_timeout_ms = 30000
    if isinstance(default_timeout_ms, bool) or not isinstance(default_timeout_ms, int):
        _audit("error", "VALIDATION_ERROR: default_timeout_ms type")
        return _err("VALIDATION_ERROR", "default_timeout_ms must be an integer")
    if default_timeout_ms < 1000 or default_timeout_ms > 300000:
        _audit("error", "VALIDATION_ERROR: default_timeout_ms range")
        return _err("VALIDATION_ERROR", "default_timeout_ms must be between 1000 and 300000")

    if console_capture_enabled is None:
        console_capture_enabled = True
    if not isinstance(console_capture_enabled, bool):
        _audit("error", "VALIDATION_ERROR: console_capture_enabled type")
        return _err("VALIDATION_ERROR", "console_capture_enabled must be boolean")

    if element_mapping_enabled is None:
        element_mapping_enabled = True
    if not isinstance(element_mapping_enabled, bool):
        _audit("error", "VALIDATION_ERROR: element_mapping_enabled type")
        return _err("VALIDATION_ERROR", "element_mapping_enabled must be boolean")

    if stability_wait_ms is None:
        stability_wait_ms = 0
    if isinstance(stability_wait_ms, bool) or not isinstance(stability_wait_ms, int):
        _audit("error", "VALIDATION_ERROR: stability_wait_ms type")
        return _err("VALIDATION_ERROR", "stability_wait_ms must be an integer")
    if stability_wait_ms < 0 or stability_wait_ms > 60000:
        _audit("error", "VALIDATION_ERROR: stability_wait_ms range")
        return _err("VALIDATION_ERROR", "stability_wait_ms must be between 0 and 60000")

    if device is not None and not isinstance(device, str):
        _audit("error", "VALIDATION_ERROR: device type")
        return _err("VALIDATION_ERROR", "device must be a string when provided")

    # Create
    sid = f"sess_{int(time.time()*1000)}_{len(sessions)+1}"
    row = {
        "id": sid,
        "status": "active",
        "origin_tool": origin_tool.strip(),
        "start_url": start_url,
        "current_url": start_url,
        "device": device,
        "default_wait_until": default_wait_until,
