        "element_mapping_enabled": element_mapping_enabled,
        "stability_wait_ms": stability_wait_ms,
        "created_at": now,
        "updated_at": now
    }
    sessions.append(row)
    _save("sessions.json", sessions)

    _audit("ok", f"session created {sid}")

    return {"session": row, "meta": {"latency_ms": int((time.time() - t0) * 1000)}}

def list_sessions(status=None, origin_tool=None, created_after=None, created_before=None, page=None, pageSize=None, **_extra):
    import json, os, datetime, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0316000" if __import__("os").path.isdir("./environment_mix/0316000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    sessions = _load("sessions.json")
    event_logs = _load("event_logs.json")

    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return prefix + "".join(random.choice(alphabet) for _ in range(20))

    def _audit(status_code, message, extra_data=None, severity=None):
        nonlocal event_logs
        sev = severity or ("info" if status_code == "ok" else ("info" if status_code == "succeeded" else "error"))
        event_logs.append({
            "id": _new_id("vuda_evt_"),
            "session_id": None,
            "job_id": None,
            "event_type": "playwright_action",
            "severity": sev,
            "message": message,
            "data": {
                "endpoint": "list_sessions",
                "status": status_code,
                "latency_ms": int((time.time() - t0) * 1000),
                **(extra_data or {})
            },
            "occurred_at": now,
            "created_at": now,
            "updated_at": now
        })
        _save("event_logs.json", event_logs)

    # Validation: align with tool parameter schema; do not over-enforce timestamp format.
    if status is not None and status not in ("active", "closing", "closed", "errored"):
        _audit("VALIDATION_ERROR", "Invalid status.", extra_data={"field": "status"})
        return _err("VALIDATION_ERROR", "status must be one of: active, closing, closed, errored", field="status")

    if origin_tool is not None and (not isinstance(origin_tool, str) or not origin_tool.strip()):
        _audit("VALIDATION_ERROR", "Invalid origin_tool.", extra_data={"field": "origin_tool"})
        return _err("VALIDATION_ERROR", "origin_tool must be a non-empty string.", field="origin_tool")

    if created_after is not None and (not isinstance(created_after, str) or not created_after.strip()):
        _audit("VALIDATION_ERROR", "Invalid created_after.", extra_data={"field": "created_after"})
        return _err("VALIDATION_ERROR", "created_after must be a string.", field="created_after")

    if created_before is not None and (not isinstance(created_before, str) or not created_before.strip()):
        _audit("VALIDATION_ERROR", "Invalid created_before.", extra_data={"field": "created_before"})
        return _err("VALIDATION_ERROR", "created_before must be a string.", field="created_before")

    if page is None:
        page = 1
    if pageSize is None:
        pageSize = 25

    if not isinstance(page, int) or page < 1:
        _audit("VALIDATION_ERROR", "Invalid page.", extra_data={"field": "page"})
        return _err("VALIDATION_ERROR", "page must be an integer >= 1.", field="page")
    if not isinstance(pageSize, int) or pageSize < 1 or pageSize > 100:
        _audit("VALIDATION_ERROR", "Invalid pageSize.", extra_data={"field": "pageSize"})
        return _err("VALIDATION_ERROR", "pageSize must be an integer between 1 and 100.", field="pageSize")

    # Parse timestamps only if they look like ISO-ish; otherwise treat as opaque (do not error),
    # yielding an empty set if filtering cannot match.
    def _parse_iso(s):
        if not isinstance(s, str):
            return None
        ss = s.strip()
        if not ss:
            return None
        # Require at least "YYYY-MM-DD" to attempt parse.
        if len(ss) < 10 or ss[4] != "-" or ss[7] != "-":
            return None
        try:
            if ss.endswith("Z"):
                ss2 = ss[:-1] + "+00:00"
            else:
                ss2 = ss
            return datetime.datetime.fromisoformat(ss2)
        except Exception:
            return None

    ca_dt = _parse_iso(created_after) if created_after is not None else None
    cb_dt = _parse_iso(created_before) if created_before is not None else None

    def _row_dt(v):
        if not isinstance(v, str):
            return None
        try:
            s = v
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    # Filter rows
    filtered = []
    for s in sessions:
        if not isinstance(s, dict):
            continue
        if status is not None and s.get("status") != status:
            continue
        if origin_tool is not None and s.get("origin_tool") != origin_tool:
            continue

        if ca_dt is not None or cb_dt is not None:
            sdt = _row_dt(s.get("created_at"))
            # If session has unparseable created_at, exclude only when time filters are in effect.
            if sdt is None:
                continue
            if ca_dt is not None and not (sdt > ca_dt):
                continue
            if cb_dt is not None and not (sdt < cb_dt):
                continue

        filtered.append(s)

    # Sort created_at desc (fallback stable by id)
    def _sort_key(r):
        dt = _row_dt(r.get("created_at"))
        return (dt is not None, dt, r.get("id") or "")
    filtered.sort(key=_sort_key, reverse=True)

    total = len(filtered)
    start = (page - 1) * pageSize
    end = start + pageSize
    page_rows = filtered[start:end]
    has_more = end < total
    next_cursor = (page + 1) if has_more else None

    _audit("ok", "Sessions listed.", extra_data={
        "filters": {
            "status": status,
            "origin_tool": origin_tool,
            "created_after": created_after,
            "created_before": created_before
        },
        "page": page,
        "pageSize": pageSize,
        "returned": len(page_rows),
        "total": total
    })

    return {
        "data": page_rows,
        "meta": {
            "total": total,
            "page": page,
            "pageSize": pageSize,
            "has_more": has_more,
            "next_cursor": next_cursor
        }
    }

