def update_session(id, status=None, current_url=None, device=None, default_wait_until=None, default_timeout_ms=None, console_capture_enabled=None, element_mapping_enabled=None, stability_wait_ms=None, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0316000" if __import__("os").path.isdir("./environment_mix/0316000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = datetime.datetime.utcnow()

    # Usage/audit logging (best-effort, only if collection exists; doesn't change success semantics)
    def _append_request_log(status_code, error_code=None, error_message=None):
        try:
            fname = None
            for cand in ("request_logs.json", "usage.json", "audit_logs.json", "api_requests.json"):
                if os.path.exists(os.path.join(_DB, cand)):
                    fname = cand
                    break
            if not fname:
                return
            logs = _load(fname)
            now = datetime.datetime.utcnow()
            latency_ms = int((now - t0).total_seconds() * 1000)
            rid = f"req_{now.strftime('%Y%m%d%H%M%S%f')}"
            row = {
                "id": rid,
                "endpoint": "update_session",
                "status": status_code,
                "error_code": error_code,
                "error_message": error_message,
                "latency_ms": latency_ms,
                "timestamp": now.isoformat(timespec="milliseconds") + "Z",
            }
            logs.append(row)
            _save(fname, logs)
        except Exception:
            return

    # Validate required
    if not isinstance(id, str) or not id.strip():
        _append_request_log(400, "VALIDATION_ERROR", "id must be a non-empty string")
        return _err("VALIDATION_ERROR", "id must be a non-empty string", field="id")

    allowed_status = {"active", "closing", "closed", "errored"}
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            _append_request_log(400, "VALIDATION_ERROR", "Invalid status")
            return _err("VALIDATION_ERROR", "Invalid status", field="status", allowed=sorted(allowed_status))

    if current_url is not None and (not isinstance(current_url, str) or not current_url.strip()):
        _append_request_log(400, "VALIDATION_ERROR", "current_url must be a non-empty string when provided")
        return _err("VALIDATION_ERROR", "current_url must be a non-empty string when provided", field="current_url")
    if device is not None and (not isinstance(device, str) or not device.strip()):
        _append_request_log(400, "VALIDATION_ERROR", "device must be a non-empty string when provided")
        return _err("VALIDATION_ERROR", "device must be a non-empty string when provided", field="device")

    allowed_wait = {"load", "domcontentloaded", "networkidle"}
    if default_wait_until is not None:
        if not isinstance(default_wait_until, str) or default_wait_until not in allowed_wait:
            _append_request_log(400, "VALIDATION_ERROR", "Invalid default_wait_until")
            return _err("VALIDATION_ERROR", "Invalid default_wait_until", field="default_wait_until", allowed=sorted(allowed_wait))

    if default_timeout_ms is not None:
        if not isinstance(default_timeout_ms, int):
            _append_request_log(400, "VALIDATION_ERROR", "default_timeout_ms must be an integer")
            return _err("VALIDATION_ERROR", "default_timeout_ms must be an integer", field="default_timeout_ms")
        if default_timeout_ms < 1000 or default_timeout_ms > 300000:
            _append_request_log(400, "VALIDATION_ERROR", "default_timeout_ms out of range")
            return _err("VALIDATION_ERROR", "default_timeout_ms out of range", field="default_timeout_ms", minimum=1000, maximum=300000)

    if console_capture_enabled is not None and not isinstance(console_capture_enabled, bool):
        _append_request_log(400, "VALIDATION_ERROR", "console_capture_enabled must be boolean")
        return _err("VALIDATION_ERROR", "console_capture_enabled must be boolean", field="console_capture_enabled")

    if element_mapping_enabled is not None and not isinstance(element_mapping_enabled, bool):
        _append_request_log(400, "VALIDATION_ERROR", "element_mapping_enabled must be boolean")
        return _err("VALIDATION_ERROR", "element_mapping_enabled must be boolean", field="element_mapping_enabled")

    if stability_wait_ms is not None:
        if not isinstance(stability_wait_ms, int):
            _append_request_log(400, "VALIDATION_ERROR", "stability_wait_ms must be an integer")
            return _err("VALIDATION_ERROR", "stability_wait_ms must be an integer", field="stability_wait_ms")
        if stability_wait_ms < 0 or stability_wait_ms > 60000:
            _append_request_log(400, "VALIDATION_ERROR", "stability_wait_ms out of range")
            return _err("VALIDATION_ERROR", "stability_wait_ms out of range", field="stability_wait_ms", minimum=0, maximum=60000)

    sessions = _load("sessions.json")
    idx = None
    for i, s in enumerate(sessions):
        if isinstance(s, dict) and s.get("id") == id:
            idx = i
            break
    if idx is None:
        _append_request_log(404, "NOT_FOUND", "Session not found")
        return _err("NOT_FOUND", "Session not found", id=id)

    sess = sessions[idx]
    if not isinstance(sess, dict):
        _append_request_log(500, "CONFLICT", "Corrupt session record")
        return _err("CONFLICT", "Corrupt session record", id=id)

    # Lifecycle transition enforcement
    if status is not None:
        cur = sess.get("status")
        transitions = {
            "active": {"closing", "errored"},
            "closing": {"closed", "errored"},
            "closed": set(),
            "errored": set(),
        }
        if cur not in transitions:
            _append_request_log(409, "CONFLICT", "Unknown current session status")
            return _err("CONFLICT", "Unknown current session status", current_status=cur)
        if status != cur:
            if status not in transitions[cur]:
                _append_request_log(400, "VALIDATION_ERROR", "Invalid status transition")
                return _err("VALIDATION_ERROR", "Invalid status transition", from_status=cur, to_status=status, allowed=sorted(transitions[cur]))
            sess["status"] = status

    # Apply mutable field updates
    if current_url is not None:
        sess["current_url"] = current_url
    if device is not None:
        sess["device"] = device
    if default_wait_until is not None:
        sess["default_wait_until"] = default_wait_until
    if default_timeout_ms is not None:
        sess["default_timeout_ms"] = default_timeout_ms
    if console_capture_enabled is not None:
        sess["console_capture_enabled"] = console_capture_enabled
    if element_mapping_enabled is not None:
        sess["element_mapping_enabled"] = element_mapping_enabled
    if stability_wait_ms is not None:
        sess["stability_wait_ms"] = stability_wait_ms

    # Enforce schema-level constraints that are relevant here
    # stability_wait_ms >= 0 (already validated when provided)
    # default_timeout_ms null or 1..300000 (validated if provided)
    if "console_capture_enabled" in sess and not isinstance(sess["console_capture_enabled"], bool):
        _append_request_log(409, "CONFLICT", "console_capture_enabled is not boolean in stored record")
        return _err("CONFLICT", "console_capture_enabled is not boolean in stored record", id=id)
    if "element_mapping_enabled" in sess and not isinstance(sess["element_mapping_enabled"], bool):
        _append_request_log(409, "CONFLICT", "element_mapping_enabled is not boolean in stored record")
        return _err("CONFLICT", "element_mapping_enabled is not boolean in stored record", id=id)
    if "stability_wait_ms" in sess:
        try:
            if sess["stability_wait_ms"] is None or float(sess["stability_wait_ms"]) < 0:
                _append_request_log(409, "CONFLICT", "stability_wait_ms violates constraint")
                return _err("CONFLICT", "stability_wait_ms violates constraint", id=id)
        except Exception:
            _append_request_log(409, "CONFLICT", "stability_wait_ms violates constraint")
            return _err("CONFLICT", "stability_wait_ms violates constraint", id=id)
    if sess.get("default_timeout_ms") is not None:
        if not isinstance(sess["default_timeout_ms"], (int, float)) or sess["default_timeout_ms"] < 1 or sess["default_timeout_ms"] > 300000:
            _append_request_log(409, "CONFLICT", "default_timeout_ms violates constraint")
            return _err("CONFLICT", "default_timeout_ms violates constraint", id=id)

    now = datetime.datetime.utcnow().isoformat(timespec="milliseconds") + "Z"
    if not sess.get("created_at"):
        sess["created_at"] = now
    sess["updated_at"] = now

    sessions[idx] = sess
    _save("sessions.json", sessions)

    _append_request_log(200)
    return {"session": sess}

