    allowed_status = {"queued", "running", "succeeded", "failed", "cancelled"}
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            _append_request_log(400, "VALIDATION_ERROR", "Invalid status")
            return _err("VALIDATION_ERROR", "Invalid status", field="status", allowed=sorted(allowed_status))

    if tool_name is not None and (not isinstance(tool_name, str) or not tool_name.strip()):
        _append_request_log(400, "VALIDATION_ERROR", "tool_name must be a non-empty string")
        return _err("VALIDATION_ERROR", "tool_name must be a non-empty string", field="tool_name")

    if page is None:
        page = 1
    if pageSize is None:
        pageSize = 25

    if not isinstance(page, int) or page < 1:
        _append_request_log(400, "VALIDATION_ERROR", "page must be an integer >= 1")
        return _err("VALIDATION_ERROR", "page must be an integer >= 1", field="page", minimum=1)
    if not isinstance(pageSize, int) or pageSize < 1 or pageSize > 100:
        _append_request_log(400, "VALIDATION_ERROR", "pageSize must be an integer between 1 and 100")
        return _err("VALIDATION_ERROR", "pageSize must be an integer between 1 and 100", field="pageSize", minimum=1, maximum=100)

    try:
        dt_after = _parse_iso(created_after, "created_after")
        dt_before = _parse_iso(created_before, "created_before")
    except ValueError as e:
        _append_request_log(400, "VALIDATION_ERROR", str(e))
        return _err("VALIDATION_ERROR", str(e))

    # Load and filter
    jobs = _load("jobs.json")

    # Optional referential filter validation: if session_id provided and doesn't exist, treat as empty set (not error)
    if session_id is not None:
        sess = _load("sessions.json")
        if not any(isinstance(s, dict) and s.get("id") == session_id for s in sess):
            jobs = []
        else:
            jobs = [j for j in jobs if isinstance(j, dict) and j.get("session_id") == session_id]
    else:
        jobs = [j for j in jobs if isinstance(j, dict)]

    if status is not None:
        jobs = [j for j in jobs if j.get("status") == status]
    if tool_name is not None:
        jobs = [j for j in jobs if j.get("tool_name") == tool_name.strip()]

    def _job_created_dt(j):
        v = j.get("created_at")
        if isinstance(v, str):
            try:
                if v.endswith("Z"):
                    return datetime.datetime.fromisoformat(v[:-1] + "+00:00")
                return datetime.datetime.fromisoformat(v)
            except Exception:
                return None
        return None

    if dt_after is not None:
        jobs = [j for j in jobs if (_job_created_dt(j) is not None and _job_created_dt(j) > dt_after)]
    if dt_before is not None:
        jobs = [j for j in jobs if (_job_created_dt(j) is not None and _job_created_dt(j) < dt_before)]

    # Sort created_at desc (unknowns last)
    def _sort_key(j):
        dt = _job_created_dt(j)
        return (dt is None, dt if dt is not None else datetime.datetime.min.replace(tzinfo=datetime.timezone.utc))
    jobs_sorted = sorted(jobs, key=_sort_key, reverse=True)

    total = len(jobs_sorted)
    start = (page - 1) * pageSize
    end = start + pageSize
    page_rows = jobs_sorted[start:end]
    has_more = end < total

    _append_request_log(200)
    return {
        "jobs": page_rows,
        "pagination": {
            "page": page,
            "pageSize": pageSize,
            "total": total,
            "has_more": has_more,
        },
    }
